fn local_codepro_event_sequence(root: &Path, run_id: &str) -> Option<u64> {
    if run_id.trim().is_empty() {
        return None;
    }
    let path = root.join(run_id).join("run").join("events.jsonl");
    crate::agents::codepro_event_log::read_codepro_event_records(path)
        .ok()?
        .into_iter()
        .rev()
        .find(|record| record.run_id == run_id && record.sequence > 0)
        .map(|record| record.sequence)
}

async fn codepro_checkpoint_event_sequence(
    runtime: Option<&CodeProRuntime>,
    event_log_root: Option<&Path>,
    session_id: &str,
    control_run_id: Option<&str>,
) -> Result<Option<u64>> {
    let Some(control_run_id) = control_run_id else {
        return Ok(None);
    };
    if let Some(runtime) = runtime {
        match RunId::new(control_run_id.to_string()) {
            Ok(run_id) => match runtime.snapshot(session_id, &run_id).await {
                Ok(snapshot) => return Ok(Some(snapshot.projection.last_sequence)),
                Err(error)
                    if runtime.mode_policy().effective()
                        == crate::agents::control_plane::CodeProRuntimeMode::Durable =>
                {
                    return Err(anyhow!(
                        "durable CodePro runtime snapshot failed for run {control_run_id}: {error}"
                    ));
                }
                Err(_) => {}
            },
            Err(error)
                if runtime.mode_policy().effective()
                    == crate::agents::control_plane::CodeProRuntimeMode::Durable =>
            {
                return Err(anyhow!(
                    "durable CodePro runtime run id is invalid ({control_run_id}): {error}"
                ));
            }
            Err(_) => {}
        }
    }
    Ok(event_log_root.and_then(|root| local_codepro_event_sequence(root, control_run_id)))
}
