pub(crate) fn compaction_lifecycle_message(
    operation_id: &str,
    started_at: &str,
    status: &str,
    trigger: &str,
    budget: Option<&crate::context_mgmt::RequestContextBudget>,
    error_message: Option<&str>,
) -> Message {
    let message = match status {
        "started" => "正在整理对话上下文…",
        "completed" => "对话上下文整理完成，正在继续当前任务。",
        "cancelled" => "对话上下文整理已取消；原任务和对话保持不变。",
        _ => "对话上下文整理失败；原任务和对话保持不变。",
    };
    let data = serde_json::json!({
        "schema_version": 1,
        "event": "compaction_lifecycle",
        "status": status,
        "trigger": trigger,
        "operation_id": operation_id,
        "started_at": started_at,
        "budget": budget.map(|value| serde_json::json!({
            "source": "local_estimate",
            "context_limit": value.context_limit,
            "projected_input_tokens": value.projected_input_tokens,
            "output_reserve_tokens": value.output_reserve_tokens,
            "projected_total_tokens": value.projected_total_tokens(),
        })),
        "error": error_message,
    });
    Message::assistant().with_system_notification_with_data(
        SystemNotificationType::ProgressMessage,
        message,
        data,
    )
}

fn should_finalize_for_turn_limit(
    turns_taken: u32,
    max_turns: u32,
    has_action_budget: bool,
) -> bool {
    !has_action_budget && max_turns > 1 && turns_taken == max_turns
}

fn execution_limit_notification(turns_taken: u32, max_turns: u32) -> Message {
    Message::assistant()
        .with_system_notification_with_data(
            SystemNotificationType::ProgressMessage,
            "Execution capacity exhausted",
            serde_json::json!({
                "event": super::subagent_handler::CODEPRO_EXECUTION_LIMIT_EVENT,
                "turns_taken": turns_taken,
                "max_turns": max_turns,
            }),
        )
        .with_visibility(false, false)
}

fn empty_finalization_message(locale: Option<&str>) -> &'static str {
    if locale.is_some_and(|locale| locale.to_ascii_lowercase().starts_with("zh")) {
        "已达到本次任务的执行上限；已完成的操作已保留，但尚未取得可确认的最终结果。"
    } else {
        "The execution limit was reached. Completed actions were preserved, but no confirmed final result is available yet."
    }
}

fn locale_output_instruction(locale: Option<&str>) -> Option<&'static str> {
    let locale = locale?.to_ascii_lowercase();
    if locale.starts_with("zh-tw") || locale.starts_with("zh-hk") {
        Some(
            "# 顯示語言\n\n優先遵循使用者明確指定的回覆語言，其次是已知語言偏好；沒有時跟隨當前請求的主要交流語言。仍無法判斷時使用介面語言繁體中文，不要為語言選擇額外提問。計畫、公開進度、結果及錯誤說明使用同一語言。不要把隱藏推理當成公開說明；專有名詞、程式碼、命令及路徑保留原文。",
        )
    } else if locale.starts_with("zh") {
        Some(
            "# 显示语言\n\n优先遵循用户明确指定的回复语言，其次是已知语言偏好；没有时跟随当前请求的主要交流语言。仍无法判断时使用界面语言简体中文，不要为语言选择额外提问。计划、公开进度、结果及错误说明使用同一语言。不要把隐藏推理当成公开说明；专有名词、代码、命令及路径保留原文。",
        )
    } else {
        None
    }
}

fn append_locale_system_instruction(
    system_prompt: &mut String,
    context_addendum: &mut String,
    locale: Option<&str>,
) {
    if let Some(instruction) = locale_output_instruction(locale) {
        for prompt in [system_prompt, context_addendum] {
            prompt.push_str("\n\n");
            prompt.push_str(instruction);
        }
    }
}

fn explicitly_forbids_tool_use(goal: &str) -> bool {
    let mut outside_quotes = String::with_capacity(goal.len());
    let mut closing_quote = None;
    for character in goal.chars() {
        if closing_quote == Some(character) {
            closing_quote = None;
            continue;
        }
        if closing_quote.is_some() {
            continue;
        }
        closing_quote = match character {
            '“' => Some('”'),
            '「' => Some('」'),
            '『' => Some('』'),
            '"' => Some('"'),
            '`' => Some('`'),
            _ => None,
        };
        if closing_quote.is_none() {
            outside_quotes.push(character);
        }
    }
    let normalized = outside_quotes.to_lowercase();
    [
        "不要调用工具",
        "不要调用任何工具",
        "不要使用工具",
        "不调用任何工具",
        "不使用任何工具",
        "无需调用工具",
        "禁止调用工具",
        "do not use tools",
        "don't use tools",
        "without using tools",
        "no tools",
    ]
    .iter()
    .any(|marker| normalized.contains(marker))
        || is_safe_literal_reply_only_request(goal)
}

fn literal_reply_parts(goal: &str) -> Option<(String, String, String)> {
    let ascii_lower = goal.to_ascii_lowercase();
    for marker in ["只回复", "仅回复", "只回答", "only reply"] {
        let marker_index = if marker.is_ascii() {
            ascii_lower.find(marker)
        } else {
            goal.find(marker)
        };
        let Some(marker_index) = marker_index else {
            continue;
        };
        let suffix = goal.get(marker_index + marker.len()..)?;
        let suffix = suffix.trim_start_matches([' ', '：', ':']);
        let mut chars = suffix.chars();
        let opening = chars.next()?;
        let closing = match opening {
            '“' => '”',
            '‘' => '’',
            '"' => '"',
            '\'' => '\'',
            _ => continue,
        };
        let remainder = chars.as_str();
        let closing_index = remainder.find(closing)?;
        let value = remainder.get(..closing_index)?.to_string();
        if !value.is_empty()
            && value.chars().count() <= 200
            && !value
                .chars()
                .any(|character| matches!(character, '\r' | '\n'))
        {
            let after = remainder.get(closing_index + closing.len_utf8()..)?;
            let prefix = goal.get(..marker_index)?;
            return Some((value, format!("{prefix} {after}"), after.to_string()));
        }
    }
    None
}

#[cfg(test)]
fn explicit_literal_reply(goal: &str) -> Option<String> {
    literal_reply_parts(goal).map(|(reply, _, _)| reply)
}

fn enforceable_literal_reply(goal: &str) -> Option<String> {
    let (reply, _, trailing) = literal_reply_parts(goal)?;
    let mut remaining = trailing.to_lowercase();
    for guard in [
        "不要调用任何工具",
        "不要调用工具",
        "不要使用任何工具",
        "不要使用工具",
        "不调用任何工具",
        "不使用任何工具",
        "无需调用工具",
        "禁止调用工具",
        "不要搜索",
        "不要执行计划",
        "不要生成执行计划",
        "不要修改文件或执行命令",
        "不要修改任何文件或执行任何命令",
        "不要修改文件，也不要执行命令",
        "不要修改任何文件，也不要执行任何命令",
        "do not use tools",
        "don't use tools",
        "without using tools",
        "do not search",
        "don't search",
        "do not execute a plan",
        "don't execute a plan",
        "do not modify files or execute commands",
        "don't modify files or execute commands",
    ] {
        remaining = remaining.replace(guard, "");
    }
    let meaningful = remaining.trim_matches(|character: char| {
        character.is_whitespace()
            || matches!(
                character,
                ',' | '.' | ':' | ';' | '!' | '?' | '，' | '。' | '：' | '；' | '！' | '？'
            )
    });
    if meaningful.is_empty()
        || matches!(
            meaningful,
            "并" | "并且" | "且" | "也" | "以及" | "and" | "also"
        )
    {
        Some(reply)
    } else {
        None
    }
}

fn is_safe_literal_reply_only_request(goal: &str) -> bool {
    let Some((_, surrounding, _)) = literal_reply_parts(goal) else {
        return false;
    };
    let mut surrounding = surrounding.to_lowercase();
    let non_action_scopes = [
        "不要修改文件或执行命令",
        "不要修改任何文件或执行任何命令",
        "不要修改文件，也不要执行命令",
        "不要修改任何文件，也不要执行任何命令",
        "do not modify files or execute commands",
        "don't modify files or execute commands",
    ];
    if !non_action_scopes
        .iter()
        .any(|scope| surrounding.contains(scope))
    {
        return false;
    }
    for scope in non_action_scopes {
        surrounding = surrounding.replace(scope, "");
    }
    ![
        "分析",
        "审查",
        "检查",
        "读取",
        "查看",
        "阅读",
        "查找",
        "搜索",
        "扫描",
        "打开",
        "列出",
        "重命名",
        "修复",
        "修改代码",
        "改代码",
        "执行测试",
        "运行测试",
        "提交",
        "推送",
        "拉取",
        "合并",
        "删除",
        "创建",
        "实现",
        "开发",
        "analyze",
        "analyse",
        "review",
        "inspect",
        "read",
        "check",
        "show",
        "find",
        "search",
        "scan",
        "open",
        "list",
        "fetch",
        "write",
        "update",
        "rename",
        "fix",
        "modify the code",
        "change the code",
        "run tests",
        "execute tests",
        "commit",
        "push",
        "pull",
        "merge",
        "delete",
        "create",
        "implement",
        "develop",
    ]
    .iter()
    .any(|action| surrounding.contains(action))
}
