fn codepro_question_request_id(requests: &[ToolRequest]) -> Option<&str> {
    requests.iter().find_map(|request| {
        request.tool_call.as_ref().ok().and_then(|call| {
            (call.name.rsplit("__").next() == Some("ask_user")).then_some(request.id.as_str())
        })
    })
}

fn codepro_unanswered_question_result(
    request: &ToolRequest,
    result: &ToolResult<CallToolResult>,
) -> bool {
    if !request
        .tool_call
        .as_ref()
        .is_ok_and(|call| call.name.rsplit("__").next() == Some("ask_user"))
    {
        return false;
    }
    result.as_ref().is_ok_and(|result| {
        result.content.iter().any(|content| {
            let rmcp::model::RawContent::Text(text) = &content.raw else {
                return false;
            };
            serde_json::from_str::<Value>(&text.text)
                .ok()
                .is_some_and(|value| value["action"] == "unanswered")
        })
    })
}

