fn codepro_task_has_plain_user_input_evidence(
    dag: &crate::agents::task_dag::TaskDAG,
    task: &crate::agents::task_dag::TaskNode,
) -> bool {
    task.output.as_ref().is_some_and(|output| {
        output
            .test_results
            .as_deref()
            .is_some_and(|evidence| evidence.starts_with("workspace_discovery_not_found"))
    }) || dag
        .verification_evidence_v1
        .get(&task.id)
        .and_then(|evidence| evidence.last())
        .is_some_and(|evidence| {
            evidence.execution_outcome == crate::agents::task_dag::ExecutionOutcome::WaitingForUser
        })
}

fn attach_validation_input_requirement(
    dag: &mut crate::agents::task_dag::TaskDAG,
    message: &Message,
) -> Result<()> {
    let source_text = agent_visible_message_text(message);
    if message.role != Role::User
        || !super::codepro_intent::explicitly_requires_validation_input(&source_text)
    {
        return Ok(());
    }
    let requirement = super::task_dag::ValidationInputRequirement {
        source_message_id: message.id.clone().context("用户前置条件缺少来源消息 ID")?,
        source_text,
    };
    for task in &dag.tasks {
        if matches!(task.role, AgentRole::Tester | AgentRole::Coder) {
            let contract = dag
                .contracts
                .get_mut(&task.id)
                .context("用户前置条件缺少目标任务合同")?;
            contract.validation_input_requirement = Some(requirement.clone());
        }
    }
    Ok(())
}

fn codepro_task_waits_for_plain_user_input(
    dag: &crate::agents::task_dag::TaskDAG,
    task: &crate::agents::task_dag::TaskNode,
) -> bool {
    task.status == crate::agents::task_dag::TaskStatus::WaitingForUser
        && codepro_task_has_plain_user_input_evidence(dag, task)
}

fn codepro_pause_plain_user_input_tasks(dag: &mut crate::agents::task_dag::TaskDAG) -> usize {
    let waiting_task_ids = dag
        .tasks
        .iter()
        .filter(|task| codepro_task_waits_for_plain_user_input(dag, task))
        .map(|task| task.id.clone())
        .collect::<std::collections::HashSet<_>>();
    let mut paused = 0;
    for task in &mut dag.tasks {
        if !waiting_task_ids.contains(&task.id) {
            continue;
        }
        task.status = crate::agents::task_dag::TaskStatus::Paused;
        if let Some(output) = task.output.as_mut() {
            output.change_report.push_str(
                "\nWAITING_FOR_USER: 请提供验证命令，或明确跳过动态验证并仅保留静态分析。",
            );
        }
        paused += 1;
    }
    paused
}

fn codepro_user_requested_validation_skip(instruction: &str) -> bool {
    matches!(
        instruction
            .trim()
            .trim_end_matches(['。', '.'])
            .to_ascii_lowercase()
            .as_str(),
        "跳过该命令，只做静态分析"
            | "跳过该命令，只做静态分析，不要修改文件"
            | "跳过动态验证"
            | "跳过测试"
            | "skip dynamic validation"
            | "skip validation"
    )
}

fn codepro_skipped_dynamic_validation(dag: &crate::agents::task_dag::TaskDAG) -> bool {
    !dag.has_failures()
        && !dag.has_paused_tasks()
        && dag
            .tasks
            .iter()
            .all(crate::agents::task_dag::TaskNode::is_terminal)
        && dag.tasks.iter().any(|task| {
            task.status == crate::agents::task_dag::TaskStatus::Skipped
                && task.output.as_ref().is_some_and(|output| {
                    output
                        .test_results
                        .as_deref()
                        .is_some_and(|evidence| evidence.contains("result:NOT_RUN"))
                })
        })
}

fn checkpoint_input_answer_target<'a>(
    state: &CodeProRunState,
    instruction: &'a str,
) -> Option<(String, &'a str)> {
    let waiting =
        state
            .dag
            .tasks
            .iter()
            .filter(|task| {
                (task.role == AgentRole::Tester
                    || (task.role == AgentRole::Coder
                        && state.dag.contracts.get(&task.id).is_some_and(|contract| {
                            contract.validation_input_requirement.is_some()
                        })
                        && state
                            .dag
                            .verification_evidence_v1
                            .get(&task.id)
                            .and_then(|items| items.last())
                            .is_some_and(|item| item.tool_ref == "host::execution_input")))
                    && task.status == crate::agents::task_dag::TaskStatus::Paused
                    && codepro_task_has_plain_user_input_evidence(&state.dag, task)
            })
            .collect::<Vec<_>>();
    let targeted = waiting.iter().find_map(|task| {
        [format!("{}:", task.id), format!("{}：", task.id)]
            .into_iter()
            .find_map(|prefix| {
                instruction
                    .trim()
                    .strip_prefix(&prefix)
                    .map(|answer| (task.id.clone(), answer.trim()))
            })
    });
    targeted.or_else(|| (waiting.len() == 1).then(|| (waiting[0].id.clone(), instruction.trim())))
}

pub(super) fn committed_checkpoint_input(
    task: &crate::agents::task_dag::TaskNode,
) -> Option<crate::agents::protocol::UserInputResolution> {
    use crate::agents::task_dag::TaskStatus;
    if !matches!(
        task.status,
        TaskStatus::Pending | TaskStatus::Ready | TaskStatus::Skipped
    ) {
        return None;
    }
    task.output
        .as_ref()?
        .test_results
        .as_deref()?
        .lines()
        .rev()
        .find_map(|line| {
            line.strip_prefix("host_input_committed:")
                .and_then(|json| serde_json::from_str(json).ok())
        })
}

pub(super) fn checkpoint_input_answer_hash(answer: &str) -> String {
    Sha256::digest(answer.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

pub(super) fn checkpoint_input_execution_hash(
    dag: &crate::agents::task_dag::TaskDAG,
    selected: &crate::agents::task_dag::TaskNode,
) -> Result<String> {
    let mut plan = dag
        .tasks
        .iter()
        .map(|candidate| {
            let task = if candidate.id == selected.id {
                selected
            } else {
                candidate
            };
            let mut dependencies = task.depends_on.clone();
            dependencies.sort();
            dependencies.dedup();
            let mut contract = dag
                .contracts
                .get(&task.id)
                .context("answered plan is missing a task contract")?
                .clone();
            for scope in [
                &mut contract.read_scope,
                &mut contract.write_scope,
                &mut contract.forbidden_scope,
            ] {
                scope.sort();
                scope.dedup();
            }
            contract
                .required_evidence
                .sort_by_key(|kind| format!("{kind:?}"));
            contract.required_evidence.dedup();
            Ok((
                &task.id,
                &task.name,
                &task.description,
                task.role,
                dependencies,
                &task.acceptance_criteria,
                contract,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    plan.sort_by(|left, right| left.0.cmp(right.0));
    Ok(checkpoint_input_answer_hash(&serde_json::to_string(&(
        &selected.id,
        dag.task_kind,
        plan,
    ))?))
}

fn resumes_committed_checkpoint_input(state: &CodeProRunState, instruction: &str) -> bool {
    let pending = state
        .dag
        .tasks
        .iter()
        .filter_map(committed_checkpoint_input)
        .collect::<Vec<_>>();
    pending.len() == 1
        && (super::tool_task::is_plain_continuation(instruction)
            || instruction.trim() == "继续执行已保存的任务")
}

fn apply_codepro_plain_user_input(state: &mut CodeProRunState, instruction: &str) -> bool {
    if resumes_committed_checkpoint_input(state, instruction) {
        return true;
    }
    let Some((task_id, answer)) = checkpoint_input_answer_target(state, instruction) else {
        return false;
    };
    let skip_validation = codepro_user_requested_validation_skip(answer);
    let command = checkpoint_input_validation_command(answer);
    if skip_validation
        && state
            .dag
            .tasks
            .iter()
            .any(|task| task.id == task_id && task.role != AgentRole::Tester)
    {
        return false;
    }
    if !skip_validation && command.is_none() {
        return false;
    }
    let description = if let Some(command) = command {
        let description = format!(
            "{}\n用户已确认执行测试。\n运行命令 `{command}`",
            crate::agents::codepro_intent::strip_planner_test_command_lines(
                &state
                    .dag
                    .tasks
                    .iter()
                    .find(|task| task.id == task_id)
                    .unwrap()
                    .description
            )
        );
        if !matches!(
            crate::agents::codepro_intent::focused_test_target(&description, &state.worktree_path),
            Some(crate::agents::codepro_intent::FocusedTestTarget::Command(selected))
                if selected == command
        ) {
            return false;
        }
        Some(description)
    } else {
        None
    };
    let task = state
        .dag
        .tasks
        .iter_mut()
        .find(|task| task.id == task_id)
        .expect("matched waiting task");
    if skip_validation {
        task.status = crate::agents::task_dag::TaskStatus::Skipped;
        let output = task.output.get_or_insert_with(Default::default);
        output
            .change_report
            .push_str("\n用户已确认跳过动态验证命令；该项保持未验证，不会伪造通过结果。");
        output
            .test_results
            .get_or_insert_with(String::new)
            .push_str("\nuser_decision:skip_dynamic_validation\nresult:NOT_RUN");
    } else {
        task.status = crate::agents::task_dag::TaskStatus::Pending;
        task.description = description.expect("host-selected validation command");
    }
    true
}

fn prepare_codepro_resume_state_from_published_checkpoint(
    mut state: CodeProRunState,
    working_dir: &std::path::Path,
    published_checkpoint_id: Option<&str>,
    retry: Option<&CodeProResumeRequest>,
    user_input: Option<&str>,
) -> Option<CodeProRunState> {
    let interrupted_planning = state.status == CodeProRunStatus::Planning
        && retry.is_none()
        && state.last_active_run_id.is_some()
        && state.dag.tasks.is_empty();
    let interrupted_running = state.status == CodeProRunStatus::Running
        && retry.is_none()
        && state.last_active_run_id.is_some()
        && !state.dag.tasks.is_empty();
    if (!interrupted_planning && !interrupted_running && state.status != CodeProRunStatus::Paused)
        || state.source_repo != working_dir
    {
        return None;
    }
    if interrupted_planning {
        return Some(state);
    }
    if retry.is_some_and(|retry| {
        if !retry.is_checkpoint_resume() {
            return true;
        }
        let expected_source_run_id = state
            .last_active_run_id
            .as_deref()
            .unwrap_or(state.run_id.as_str());
        retry.checkpoint_id.as_deref() != published_checkpoint_id
            || expected_source_run_id != retry.source_run_id
    }) {
        return None;
    }

    let is_user_scope_resume = state.pause_reason == Some(CodeProPauseReason::RecoveryPaused)
        && retry.is_some_and(CodeProResumeRequest::is_checkpoint_resume);
    let is_plain_user_input_resume = state.pause_reason
        == Some(CodeProPauseReason::UserInputRequired)
        && retry.is_some_and(CodeProResumeRequest::is_checkpoint_resume);
    if is_plain_user_input_resume
        && !apply_codepro_plain_user_input(
            &mut state,
            retry
                .and_then(|retry| retry.normalized_user_input.as_deref())
                .or(user_input)?,
        )
    {
        return None;
    }
    if is_user_scope_resume {
        let retry = retry?;
        let checkpoint_id = retry.checkpoint_id.as_deref()?;
        let expected_scope = codepro_checkpoint_approval_scope(checkpoint_id);
        let now = chrono::Utc::now();
        let approval = retry.approval.as_ref()?;
        if approval.scope != expected_scope
            || approval.granted_at > now
            || approval.expires_at <= now
        {
            return None;
        }
        state.dag.reset_user_scope_completion_checkpoints();
    }

    if LegacyReadyAdapter::validate(&state.dag).is_err() {
        return None;
    }
    if state.dag.has_exhausted_completion_checkpoint() {
        return None;
    }
    if let Some(task_kind) = state.dag.task_kind {
        let workflow_matches_task_kind = match state.workflow {
            Some(CodeProWorkflow::Test) => matches!(
                task_kind,
                CodeProTaskKind::FocusedTest | CodeProTaskKind::ProjectTest
            ),
            Some(CodeProWorkflow::Change) => matches!(
                task_kind,
                CodeProTaskKind::SimpleChange
                    | CodeProTaskKind::BugFix
                    | CodeProTaskKind::ComplexChange
            ),
            None => false,
        };
        if !workflow_matches_task_kind || state.dag.ensure_action_budget(task_kind).is_err() {
            return None;
        }
    }
    if state.dag.validate().is_err() {
        return None;
    }
    if is_user_scope_resume {
        state.dag.grant_recorded_scope_to_paused_workers();
        if state.dag.validate().is_err() {
            return None;
        }
    }
    if !state.dag.contract_violations().is_empty() {
        return None;
    }
    let coder_ids = state
        .dag
        .tasks
        .iter()
        .filter(|task| task.role == AgentRole::Coder)
        .map(|task| task.id.as_str())
        .collect::<Vec<_>>();
    let has_tester = state
        .dag
        .tasks
        .iter()
        .any(|task| task.role == AgentRole::Tester);
    let workflow_roles_are_valid = match state.workflow {
        Some(CodeProWorkflow::Test) => coder_ids.is_empty() && has_tester,
        Some(CodeProWorkflow::Change) => {
            !coder_ids.is_empty()
                && coder_ids
                    .iter()
                    .all(|coder_id| codepro_dag_has_downstream_tester(&state.dag, coder_id))
        }
        None => false,
    };
    if !workflow_roles_are_valid {
        return None;
    }
    if !is_plain_user_input_resume {
        state.dag.resume_cancelled_tasks();
        state.dag.resume_paused_tasks();
    }
    Some(state)
}

#[cfg(test)]
fn prepare_codepro_resume_state(
    state: CodeProRunState,
    working_dir: &std::path::Path,
    retry: Option<&CodeProResumeRequest>,
) -> Option<CodeProRunState> {
    let legacy_checkpoint_id = state.run_id.clone();
    prepare_codepro_resume_state_from_published_checkpoint(
        state,
        working_dir,
        Some(&legacy_checkpoint_id),
        retry,
        None,
    )
}

fn codepro_dag_has_downstream_tester(
    dag: &crate::agents::task_dag::TaskDAG,
    source_task_id: &str,
) -> bool {
    let mut frontier = VecDeque::from([source_task_id]);
    let mut visited = Vec::new();
    while let Some(task_id) = frontier.pop_front() {
        if visited.contains(&task_id) {
            continue;
        }
        visited.push(task_id);
        for dependent in dag.tasks.iter().filter(|task| {
            task.depends_on
                .iter()
                .any(|dependency| dependency == task_id)
        }) {
            if dependent.role == AgentRole::Tester {
                return true;
            }
            frontier.push_back(dependent.id.as_str());
        }
    }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CodeProResumeRequest {
    pub(crate) normalized_user_input: Option<String>,
    pub(crate) strategy: CodeProRetryStrategy,
    pub(crate) checkpoint_id: Option<String>,
    pub(crate) source_run_id: String,
    pub(crate) source_user_message_id: String,
    pub(crate) source_terminal_message_id: Option<String>,
    pub(crate) approval: Option<CheckpointApproval>,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct CodeProCheckpointContext {
    pub(crate) schema_version: u8,
    pub(crate) checkpoint_id: String,
    pub(crate) source_run_id: String,
    pub(crate) source_user_message_id: String,
    pub(crate) source_terminal_message_id: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum CodeProCheckpointInputDecision {
    Resume(CodeProResumeRequest),
    Inspect(CodeProCheckpointContext),
    Classify(CodeProCheckpointContext),
    Notice {
        context: Option<CodeProCheckpointContext>,
        text: String,
        cancelled: bool,
    },
}

fn checkpoint_input_terminal(
    messages: &[Message],
    session_id: &str,
    state: &CodeProRunState,
    checkpoint_id: &str,
    candidate: Option<&CodeProCheckpointContext>,
) -> Option<CodeProCheckpointContext> {
    let source_run_id = state.last_active_run_id.as_deref()?;
    let (terminal_index, message, terminal) =
        messages
            .iter()
            .enumerate()
            .rev()
            .find_map(|(index, message)| {
                message.content.iter().find_map(|content| {
                    let notification = content.as_system_notification()?;
                    if notification.notification_type != SystemNotificationType::TurnTerminal {
                        return None;
                    }
                    let data = notification.data.as_ref()?;
                    (data.get("run_id")?.as_str()? == source_run_id)
                        .then_some((index, message, data))
                })
            })?;
    let string = |key: &str| terminal.get(key).and_then(serde_json::Value::as_str);
    let terminal_id = string("terminal_message_id")?;
    let source_id = string("source_user_message_id")?;
    if message.role != Role::Assistant
        || !message.is_user_visible()
        || message.id.as_deref() != Some(terminal_id)
        || terminal.get("schema_version")?.as_u64()? != 1
        || string("session_id") != Some(session_id)
        || string("status") != Some("interrupted")
        || string("checkpoint_id") != Some(checkpoint_id)
        || string("retry_strategy") != Some("continue_checkpoint")
    {
        return None;
    }
    let source_indices = messages
        .iter()
        .enumerate()
        .filter_map(|(index, message)| {
            (message.role == Role::User
                && message.is_user_visible()
                && message.id.as_deref() == Some(source_id))
            .then_some(index)
        })
        .collect::<Vec<_>>();
    if source_indices.len() != 1 || source_indices[0] >= terminal_index {
        return None;
    }
    let context = CodeProCheckpointContext {
        schema_version: 1,
        checkpoint_id: checkpoint_id.to_string(),
        source_run_id: source_run_id.to_string(),
        source_user_message_id: source_id.to_string(),
        source_terminal_message_id: Some(terminal_id.to_string()),
    };
    if candidate.is_some_and(|candidate| {
        candidate.schema_version != 1
            || candidate.checkpoint_id != context.checkpoint_id
            || candidate.source_run_id != context.source_run_id
            || candidate.source_user_message_id != context.source_user_message_id
            || candidate
                .source_terminal_message_id
                .as_ref()
                .is_some_and(|id| Some(id) != context.source_terminal_message_id.as_ref())
    }) {
        return None;
    }
    Some(context)
}

fn checkpoint_input_is_cancel(instruction: &str) -> bool {
    matches!(
        instruction
            .trim()
            .trim_end_matches(['。', '！', '!', '.'])
            .to_ascii_lowercase()
            .as_str(),
        "取消当前任务"
            | "取消任务"
            | "取消"
            | "停止"
            | "不要继续了"
            | "cancel"
            | "cancel current task"
            | "stop"
    )
}

pub(super) fn checkpoint_input_validation_command(instruction: &str) -> Option<&str> {
    let instruction = instruction.trim();
    let command = [
        "验证命令是 ",
        "验证命令是",
        "验证命令：",
        "验证命令:",
        "命令是 ",
        "命令：",
    ]
    .iter()
    .find_map(|prefix| instruction.strip_prefix(prefix))
    .unwrap_or(instruction)
    .trim()
    .trim_matches('`');
    (command.chars().count() <= 2_000 && is_validation_command(command)).then_some(command)
}

fn checkpoint_input_decision(
    state: &CodeProRunState,
    context: CodeProCheckpointContext,
    user_message: &Message,
) -> CodeProCheckpointInputDecision {
    let input = agent_visible_message_text(user_message);
    let notice = |text: String, cancelled| CodeProCheckpointInputDecision::Notice {
        context: Some(context.clone()),
        text,
        cancelled,
    };
    if checkpoint_input_is_cancel(&input) {
        return notice(
            "已取消当前任务。历史记录和已保存的检查点会保留。".to_string(),
            true,
        );
    }
    if state.pause_reason == Some(CodeProPauseReason::UserInputRequired)
        && matches!(
            input.trim().to_lowercase().as_str(),
            "确认" | "確認" | "confirm"
        )
    {
        return notice(
            format!(
                "当前暂停步骤等待的是可执行验证命令；单独回复“{}”不会恢复执行。请提供“任务ID: 验证命令”，或回复“任务ID: 跳过该命令，只做静态分析”。原消息、原任务和检查点已保留。",
                input.trim()
            ),
            false,
        );
    }
    if detect_codepro_constraint_in_workspace(&input, &state.source_repo)
        == CodeProConstraint::ReadOnly
        && !codepro_user_requested_validation_skip(&input)
    {
        return CodeProCheckpointInputDecision::Inspect(context);
    }
    let explicit_continue =
        super::tool_task::is_plain_continuation(&input) || input.trim() == "继续执行已保存的任务";
    let is_answer = if state.pause_reason == Some(CodeProPauseReason::UserInputRequired) {
        let mut probe = state.clone();
        apply_codepro_plain_user_input(&mut probe, &input)
    } else {
        false
    };
    if is_answer
        || (explicit_continue
            && matches!(
                state.pause_reason,
                Some(CodeProPauseReason::RecoveryPaused | CodeProPauseReason::CheckpointPaused)
            ))
    {
        let approval = if explicit_continue
            && state.pause_reason == Some(CodeProPauseReason::RecoveryPaused)
        {
            let now = chrono::Utc::now();
            Some(CheckpointApproval {
                scope: codepro_checkpoint_approval_scope(&context.checkpoint_id),
                granted_at: now,
                expires_at: now + chrono::Duration::minutes(15),
            })
        } else {
            None
        };
        return CodeProCheckpointInputDecision::Resume(CodeProResumeRequest {
            normalized_user_input: None,
            strategy: CodeProRetryStrategy::ContinueCheckpoint,
            checkpoint_id: Some(context.checkpoint_id),
            source_run_id: context.source_run_id,
            source_user_message_id: context.source_user_message_id,
            source_terminal_message_id: context.source_terminal_message_id,
            approval,
        });
    }
    if state.pause_reason == Some(CodeProPauseReason::UserInputRequired) {
        if let Some((task_id, answer)) = checkpoint_input_answer_target(state, &input) {
            if let Some(command) = checkpoint_input_validation_command(answer) {
                return notice(
                    format!(
                        "尚未执行命令“{command}”：当前暂停步骤 {task_id} 的测试执行器不支持此命令或测试范围。请提供该步骤支持的测试命令，或回复“{task_id}: 跳过该命令，只做静态分析”。原消息、原任务和检查点已保留。"
                    ),
                    false,
                );
            }
        }
    }
    if explicit_continue
        || (state.pause_reason == Some(CodeProPauseReason::UserInputRequired)
            && (codepro_user_requested_validation_skip(&input)
                || checkpoint_input_validation_command(&input).is_some()))
    {
        let waiting = state
            .dag
            .tasks
            .iter()
            .filter(|task| {
                task.status == crate::agents::task_dag::TaskStatus::Paused
                    && codepro_task_has_plain_user_input_evidence(&state.dag, task)
            })
            .map(|task| format!("{}：{}", task.id, task.description))
            .collect::<Vec<_>>()
            .join("\n");
        return notice(
            format!(
                "原任务仍在等待输入，尚未完成。请提供要运行的验证命令，或回复“跳过该命令，只做静态分析”。有多个步骤时，请使用“任务ID: 验证命令”或“任务ID: 跳过该命令，只做静态分析”指定对应步骤。\n{waiting}"
            ),
            false,
        );
    }
    if matches!(
        detect_codepro_constraint_in_workspace(&input, &state.source_repo),
        CodeProConstraint::Change | CodeProConstraint::Test
    ) {
        return notice("当前对话仍有未完成的任务。新写入目标的任务切换尚未支持，请从“新任务”创建该目标；原目标和检查点已保留。".to_string(), false);
    }
    if detect_codepro_constraint_in_workspace(&input, &state.source_repo)
        == CodeProConstraint::ModelDecision
    {
        CodeProCheckpointInputDecision::Classify(context)
    } else {
        CodeProCheckpointInputDecision::Inspect(context)
    }
}

fn checkpoint_input_semantic_decision(
    context: CodeProCheckpointContext,
    intent: CodeProIntentDecision,
) -> CodeProCheckpointInputDecision {
    let text = if intent.warning.is_some() {
        Some("本轮输入的意图尚未确认，旧任务和检查点已保留。请明确是在回答原问题、只读分析，还是需要创建新任务。".to_string())
    } else {
        match intent.intent {
            CodeProIntent::ReadOnly | CodeProIntent::Conversation => None,
            CodeProIntent::Change | CodeProIntent::Test | CodeProIntent::ToolAction => Some(
                "当前对话仍有未完成的任务。新执行目标的任务切换尚未支持，请从“新任务”创建该目标；原目标和检查点已保留。".to_string()),
            CodeProIntent::Clarify => Some(intent.clarification.unwrap_or_else(|| "请明确本轮输入与原任务的关系；原任务和检查点已保留。".to_string())),
        }
    };
    match text {
        Some(text) => CodeProCheckpointInputDecision::Notice {
            context: Some(context),
            text,
            cancelled: false,
        },
        None => CodeProCheckpointInputDecision::Inspect(context),
    }
}

#[derive(serde::Deserialize)]
#[serde(rename_all = "snake_case")]
enum CheckpointInputKind {
    Answer,
    Inspect,
    NewTask,
    Clarify,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct CheckpointInputSuggestion {
    kind: CheckpointInputKind,
    task_id: Option<String>,
    command: Option<String>,
    clarification: Option<String>,
}

fn checkpoint_input_suggestion(
    state: &CodeProRunState,
    context: CodeProCheckpointContext,
    user_message: &Message,
    response: &str,
) -> CodeProCheckpointInputDecision {
    let unresolved = |text: &str| CodeProCheckpointInputDecision::Notice {
        context: Some(context.clone()),
        text: text.to_string(),
        cancelled: false,
    };
    let input = agent_visible_message_text(user_message);
    if checkpoint_input_is_cancel(&input) {
        return checkpoint_input_decision(state, context, user_message);
    }
    if detect_codepro_constraint_in_workspace(&input, &state.source_repo)
        == CodeProConstraint::ReadOnly
    {
        return CodeProCheckpointInputDecision::Inspect(context);
    }
    let parsed = response
        .find('{')
        .zip(response.rfind('}'))
        .and_then(|(start, end)| response.get(start..=end))
        .and_then(|json| serde_json::from_str::<CheckpointInputSuggestion>(json).ok());
    let Some(suggestion) = parsed else {
        return unresolved(
            "未能确认本轮输入与原问题的对应关系。请提供任务 ID 和验证命令，或说明要只读分析；原任务仍保留。",
        );
    };
    match suggestion.kind {
        CheckpointInputKind::Inspect => CodeProCheckpointInputDecision::Inspect(context),
        CheckpointInputKind::NewTask => checkpoint_input_semantic_decision(
            context,
            CodeProIntentDecision {
                intent: CodeProIntent::Change,
                clarification: None,
                public_summary: None,
                warning: None,
            },
        ),
        CheckpointInputKind::Clarify => unresolved(
            suggestion
                .clarification
                .as_deref()
                .filter(|text| !text.trim().is_empty())
                .unwrap_or("请明确本轮输入是在回答哪个步骤的问题；旧任务和检查点已保留。"),
        ),
        CheckpointInputKind::Answer => {
            if state.pause_reason != Some(CodeProPauseReason::UserInputRequired) {
                return unresolved("当前检查点不在等待此类答案，未恢复任何步骤。");
            }
            let Some(task_id) = suggestion.task_id else {
                return unresolved("请说明这份信息对应哪个等待步骤；未恢复任何步骤。");
            };
            let matching = state
                .dag
                .tasks
                .iter()
                .filter(|task| {
                    task.id == task_id
                        && task.role == AgentRole::Tester
                        && task.status == crate::agents::task_dag::TaskStatus::Paused
                        && codepro_task_has_plain_user_input_evidence(&state.dag, task)
                })
                .count();
            let pending_count = state
                .dag
                .tasks
                .iter()
                .filter(|task| {
                    task.status == crate::agents::task_dag::TaskStatus::Paused
                        && codepro_task_has_plain_user_input_evidence(&state.dag, task)
                })
                .count();
            let Some(command) = suggestion
                .command
                .filter(|command| is_validation_command(command))
            else {
                return unresolved(
                    "仍缺少可验证的测试命令。请提供具体命令，或明确回复“跳过该命令，只做静态分析”。",
                );
            };
            let has_image = user_message
                .content
                .iter()
                .any(|content| matches!(content, MessageContent::Image(_)));
            let explicit_target = input.trim_start().starts_with(&format!("{task_id}:"))
                || input.trim_start().starts_with(&format!("{task_id}："));
            if matching != 1
                || (pending_count > 1 && !explicit_target)
                || (!has_image && !input.contains(command.trim()))
            {
                return unresolved(
                    "答案未能唯一对应当前问题，或命令不在本轮输入中。请提供任务 ID 与实际验证命令。",
                );
            }
            let normalized = format!("{task_id}: {}", command.trim());
            let candidate = checkpoint_input_decision(
                state,
                context.clone(),
                &Message::user().with_text(&normalized),
            );
            match candidate {
                CodeProCheckpointInputDecision::Resume(mut retry) => {
                    retry.approval = None;
                    retry.normalized_user_input = Some(normalized);
                    CodeProCheckpointInputDecision::Resume(retry)
                }
                notice @ CodeProCheckpointInputDecision::Notice { .. } => notice,
                _ => unresolved("该答案还不足以恢复对应步骤，请核对任务 ID 和验证命令。"),
            }
        }
    }
}

async fn checkpoint_input_model_response<F>(
    response: F,
    cancel_token: &CancellationToken,
    timeout: std::time::Duration,
) -> CheckpointModelResponse
where
    F: std::future::Future<Output = Result<String>>,
{
    tokio::select! {
        biased;
        _ = cancel_token.cancelled() => CheckpointModelResponse::Cancelled,
        result = tokio::time::timeout(timeout, response) => match result {
            Ok(Ok(text)) => CheckpointModelResponse::Completed(text),
            Ok(Err(error)) => CheckpointModelResponse::ProviderError(error),
            Err(_) => CheckpointModelResponse::TimedOut,
        },
    }
}

enum CheckpointModelResponse {
    Completed(String),
    Cancelled,
    TimedOut,
    ProviderError(anyhow::Error),
}

impl CheckpointModelResponse {
    fn diagnostic_outcome(&self) -> &'static str {
        match self {
            Self::Completed(_) => "response_received",
            Self::Cancelled => "cancelled",
            Self::TimedOut => "timed_out",
            Self::ProviderError(_) => "provider_error",
        }
    }

    fn into_result(self) -> Result<String> {
        match self {
            Self::Completed(text) => Ok(text),
            Self::Cancelled => anyhow::bail!("已取消恢复判断，原任务没有改变"),
            Self::TimedOut => anyhow::bail!("恢复判断等待模型超时，原任务没有改变；可稍后重试"),
            Self::ProviderError(error) => {
                let activation =
                    error.downcast_ref::<crate::agents::model_router::ProviderActivationFailure>();
                tracing::warn!(
                    error_kind = error
                        .downcast_ref::<ProviderError>()
                        .map(ProviderError::telemetry_type)
                        .unwrap_or("activation_or_internal"),
                    activation = activation.map(ToString::to_string),
                    "CodePro input relation request failed before applying user input"
                );
                if let Some(activation) = activation {
                    return Err(anyhow!(
                        "未能处理这次追问（{}），原任务没有改变；请检查对应模型连接后重试",
                        activation.user_message()
                    ));
                }
                if error
                    .downcast_ref::<clarification::InputRelationImageError>()
                    .is_some()
                {
                    return Err(error);
                }
                if let Some(provider_error) = error.downcast_ref::<ProviderError>() {
                    let reason = match provider_error {
                        ProviderError::Authentication(_) => "模型认证失败，请检查 API 密钥",
                        ProviderError::NetworkError(_) => {
                            "模型连接失败，请检查服务地址与网络后重试"
                        }
                        ProviderError::RateLimitExceeded { .. } => "模型服务限流，请稍后重试",
                        ProviderError::ContextLengthExceeded(_) => {
                            "请求超过模型上下文限制，请减少输入或附件"
                        }
                        ProviderError::RequestFailed(_) => {
                            "模型拒绝了请求，请检查所选模型的图片能力和请求设置"
                        }
                        _ => "模型服务请求失败，请检查服务状态后重试",
                    };
                    return Err(error.context(format!("{reason}；原任务没有改变")));
                }
                Err(error.context("模型服务未能完成恢复判断，原任务没有改变"))
            }
        }
    }
}

#[derive(Default)]
struct CodeProRunContext {
    active_run_id: Option<String>,
    resume_request: Option<CodeProResumeRequest>,
    intent_progress_announced: bool,
    classification_source: CodeProClassificationSource,
    simple_change: Option<SimpleChangeRequest>,
    project_memory_management: bool,
    focused_test: bool,
}

#[cfg(test)]
#[path = "codepro_routing_evidence_tests.rs"]
mod routing_evidence_tests;

struct FailedValidationRetryRequest {
    run_id: String,
    source_user_message_id: String,
    source_terminal_message_id: String,
    source: Result<(ValidationRetrySource, PathBuf), String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CodeProRetryStrategy {
    ContinueCheckpoint,
    ResumeAfterWorkspace,
    ReplayUserRequest,
    RetryFailedValidation,
}

impl CodeProResumeRequest {
    fn is_checkpoint_resume(&self) -> bool {
        self.strategy == CodeProRetryStrategy::ContinueCheckpoint
    }
}

fn should_persist_codepro_user_message(resume_request: Option<&CodeProResumeRequest>) -> bool {
    !resume_request
        .is_some_and(|retry| retry.strategy == CodeProRetryStrategy::ResumeAfterWorkspace)
}

fn codepro_state_not_found(error: &anyhow::Error) -> bool {
    error.chain().any(|cause| {
        cause
            .downcast_ref::<std::io::Error>()
            .is_some_and(|error| error.kind() == std::io::ErrorKind::NotFound)
    })
}

async fn load_codepro_state_if_present(
    store: &CodeProStateStore,
    run_id: &str,
) -> Result<Option<CodeProRunState>> {
    match store.load(run_id).await {
        Ok(state) => Ok(Some(state)),
        Err(error) if codepro_state_not_found(&error) => Ok(None),
        Err(error) => Err(error.context("CodePro persisted run state is invalid")),
    }
}

fn codepro_resume_requires_workspace_rebinding(state: Option<&CodeProRunState>) -> bool {
    state
        .and_then(|state| state.workspace.as_ref())
        .is_some_and(|workspace| workspace.mode == CodeProWorkspaceMode::LegacyUnresolved)
}

fn codepro_execution_user_message(
    persisted_messages: &[Message],
    submitted_message: Message,
    resume_request: Option<&CodeProResumeRequest>,
) -> Result<Message> {
    let Some(retry) =
        resume_request.filter(|retry| retry.strategy == CodeProRetryStrategy::ResumeAfterWorkspace)
    else {
        return Ok(submitted_message);
    };
    persisted_messages
        .iter()
        .find(|message| {
            message.role == Role::User
                && message.id.as_deref() == Some(&retry.source_user_message_id)
        })
        .cloned()
        .map(|message| message.with_visibility(false, true))
        .ok_or_else(|| anyhow!("CodePro retry source message was not found"))
}

fn codepro_checkpoint_approval_scope(checkpoint_id: &str) -> String {
    format!("continue_checkpoint:{checkpoint_id}")
}

fn is_matching_codepro_linked_replay(
    state: &CodeProRunState,
    working_dir: &std::path::Path,
    retry: &CodeProResumeRequest,
) -> bool {
    retry.strategy == CodeProRetryStrategy::ReplayUserRequest
        && state.source_repo == working_dir
        && state
            .last_active_run_id
            .as_deref()
            .unwrap_or(state.run_id.as_str())
            == retry.source_run_id
}

fn is_compatible_codepro_linked_replay_state(
    state: Option<&CodeProRunState>,
    working_dir: &std::path::Path,
    retry: &CodeProResumeRequest,
) -> bool {
    state.is_none_or(|state| is_matching_codepro_linked_replay(state, working_dir, retry))
}

