impl AgentConfig {
    pub fn new(
        session_manager: Arc<SessionManager>,
        permission_manager: Arc<PermissionManager>,
        scheduler_service: Option<Arc<dyn SchedulerTrait>>,
        goose_mode: GooseMode,
        disable_session_naming: bool,
        goose_platform: GoosePlatform,
    ) -> Self {
        Self {
            session_manager,
            permission_manager,
            scheduler_service,
            goose_mode,
            disable_session_naming,
            goose_platform,
            mcp_host_info: None,
            session_name_update_tx: None,
            use_login_shell_path: None,
            codepro_evidence: None,
            codepro_event_log_root: None,
            codepro_permission_scope: None,
            codepro_agent_role: None,
            codepro_worker_events: None,
            codepro_tester_runtime: None,
            codepro_runtime: None,
            continuation_workspace_verifier: None,
            codepro_http_attempt_gate: None,
            model_router_provider_factory: None,
        }
    }

    pub fn with_mcp_host_info(mut self, mcp_host_info: Option<GooseMcpHostInfo>) -> Self {
        self.mcp_host_info = mcp_host_info;
        self
    }

    pub fn with_session_name_update_tx(
        mut self,
        tx: Option<mpsc::UnboundedSender<SessionNameUpdate>>,
    ) -> Self {
        self.session_name_update_tx = tx;
        self
    }

    pub fn with_use_login_shell_path(mut self, use_login_shell_path: bool) -> Self {
        self.use_login_shell_path = Some(use_login_shell_path);
        self
    }

    pub fn with_codepro_evidence(mut self, evidence: Arc<CodeProEvidence>) -> Self {
        self.codepro_evidence = Some(evidence);
        self
    }

    pub fn with_codepro_event_log_root(mut self, root: PathBuf) -> Self {
        self.codepro_event_log_root = Some(root);
        self
    }

    pub fn with_codepro_permission_scope(mut self, scope: CodeProTaskScope) -> Self {
        self.codepro_permission_scope = Some(scope);
        self
    }

    pub fn with_codepro_agent_role(mut self, role: AgentRole) -> Self {
        self.codepro_agent_role = Some(role);
        self
    }

    pub(crate) fn with_codepro_tester_runtime(
        mut self,
        runtime: Option<TesterRuntimeProbe>,
    ) -> Self {
        self.codepro_tester_runtime = runtime;
        self
    }

    pub(crate) fn with_codepro_http_attempt_gate(
        mut self,
        gate: Arc<dyn goose_providers::retry::HttpAttemptGate>,
    ) -> Self {
        self.codepro_http_attempt_gate = Some(gate);
        self
    }

    pub fn with_codepro_runtime(mut self, runtime: CodeProRuntime) -> Self {
        self.codepro_runtime = Some(runtime);
        self
    }

    pub(crate) fn with_continuation_workspace_verifier(
        mut self,
        verifier: ContinuationWorkspaceVerifier,
    ) -> Self {
        self.continuation_workspace_verifier = Some(verifier);
        self
    }

    pub(crate) fn with_model_router_provider_factory(
        mut self,
        provider_factory: ModelRouterProviderFactory,
    ) -> Self {
        self.model_router_provider_factory = Some(provider_factory);
        self
    }

    pub(crate) fn resolve_use_login_shell_path(&self) -> bool {
        resolve_use_login_shell_path(self.use_login_shell_path, &self.goose_platform)
    }

    pub(crate) fn resolve_codepro_event_log_root(&self) -> Option<PathBuf> {
        if let Some(root) = &self.codepro_event_log_root {
            return Some(root.clone());
        }
        if !matches!(self.goose_platform, GoosePlatform::GooseDesktop) {
            return None;
        }
        match CodeProStateStore::default_location() {
            Ok(root) => Some(root),
            Err(error) => {
                warn!("无法确定 CodePro 程序化事件日志目录，继续运行但不持久化活动：{error}");
                None
            }
        }
    }
}

fn resolve_use_login_shell_path(explicit: Option<bool>, platform: &GoosePlatform) -> bool {
    explicit.unwrap_or(matches!(platform, GoosePlatform::GooseDesktop))
}

fn host_audit_identity(
    role: Option<AgentRole>,
    host_model: Option<(&str, &goose_providers::model::ModelConfig)>,
) -> (ToolAuditActor, EffectiveModel) {
    let actor = match role {
        Some(AgentRole::Planner) => ToolAuditActor::CodeproPlanner,
        Some(AgentRole::Coder) => ToolAuditActor::CodeproCoder,
        Some(AgentRole::Tester) => ToolAuditActor::CodeproTester,
        Some(AgentRole::Reviewer) => ToolAuditActor::CodeproReviewer,
        None => ToolAuditActor::Primary,
    };
    let effective_model = host_model
        .and_then(|(provider, model_config)| {
            EffectiveModel::new(format!("{provider}/{}", model_config.model_name)).ok()
        })
        .unwrap_or_else(|| EffectiveModel::new("unknown").expect("unknown is a valid model"));
    (actor, effective_model)
}

