fn project_message_for_user_event(message: &Message) -> Message {
    message.user_visible_content()
}

fn agent_visible_message_text(message: &Message) -> String {
    message.agent_visible_content().as_concat_text()
}

fn codepro_goal_excerpt(goal: &str) -> String {
    let normalized = goal.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.is_empty() {
        return "当前请求".to_string();
    }
    let mut excerpt = normalized.chars().take(96).collect::<String>();
    if normalized.chars().count() > 96 {
        excerpt.push('…');
    }
    excerpt
}

fn codepro_intent_progress_details(goal: &str) -> String {
    format!(
        "我先确认“{}”的目标和约束，再判断直接回复、使用工具还是进入执行计划。",
        codepro_goal_excerpt(goal)
    )
}

fn codepro_intent_progress_message(goal: &str) -> String {
    format!("CodePro · 思考\n{}", codepro_intent_progress_details(goal))
}

fn codepro_intent_warning_notification(
    warning: CodeProIntentWarning,
    _fallback_intent: CodeProIntent,
) -> Message {
    let reason = match warning {
        CodeProIntentWarning::SemanticRouterUnavailable => "意图识别服务暂时不可用",
        CodeProIntentWarning::SemanticRouterInvalidOutput => "意图识别结果无效",
    };
    Message::assistant().with_system_notification(
        SystemNotificationType::InlineMessage,
        format!("{reason}；原任务和授权边界已保留，本轮未进入其他执行路径，可以直接重试。"),
    )
}

fn codepro_risk_tier_label(tier: CodeProRiskTier) -> &'static str {
    match tier {
        CodeProRiskTier::L0ReadOnly => "L0 只读",
        CodeProRiskTier::L1ReversibleChange => "L1 可逆修改",
        CodeProRiskTier::L2Feature => "L2 普通功能",
        CodeProRiskTier::L3HighRiskRelease => "L3 高风险/发布",
    }
}

fn codepro_risk_reason_label(reason: CodeProRiskReason) -> &'static str {
    match reason {
        CodeProRiskReason::ReadOnly => "只读操作",
        CodeProRiskReason::FocusedLocalValidation => "聚焦本地验证",
        CodeProRiskReason::SingleWorkspaceFile => "单个工作区文件",
        CodeProRiskReason::MultiFileOrUnknownWriteScope => "多文件或写入范围未知",
        CodeProRiskReason::PermissionBoundary => "权限边界",
        CodeProRiskReason::CredentialMaterial => "凭据材料",
        CodeProRiskReason::DestructiveChange => "破坏性修改",
        CodeProRiskReason::OutsideWorkspace => "工作区外操作",
        CodeProRiskReason::RemoteSideEffect => "远程副作用",
        CodeProRiskReason::InstallUpdateOrRelease => "安装、更新或发布",
        CodeProRiskReason::UserRequestedStricterReview => "用户要求更严格审查",
    }
}

fn codepro_execution_flow(plan: &CodeProRolePlan) -> &'static str {
    if plan.roles.contains(&AgentRole::Reviewer) {
        "分析 → 编码 → 独立测试 → 独立审查"
    } else if plan.roles.contains(&AgentRole::Coder) {
        "分析 → 编码 → 独立测试"
    } else if plan.roles == [AgentRole::Tester] {
        "独立测试"
    } else if plan.roles.contains(&AgentRole::Tester) {
        "分析 → 独立测试"
    } else if plan.task_kind == CodeProTaskKind::SimpleChange {
        "分析 → 修改 → 自动验证"
    } else {
        "分析"
    }
}

fn codepro_execution_strategy_activity(
    plan: &CodeProRolePlan,
    session_id: &str,
    run_id: &str,
    previous_risk_tier: Option<CodeProRiskTier>,
) -> CodeProAnalysisActivity {
    let tier_label = codepro_risk_tier_label(plan.risk_tier);
    let flow = codepro_execution_flow(plan);
    let reasons = plan
        .risk_reasons
        .iter()
        .copied()
        .map(codepro_risk_reason_label)
        .collect::<Vec<_>>()
        .join("、");
    let title = if previous_risk_tier.is_some() {
        "执行风险已升级"
    } else {
        "已确定执行策略"
    };
    let level = previous_risk_tier.map_or_else(
        || format!("执行级别：{tier_label}"),
        |previous| {
            format!(
                "风险已升级：{} → {tier_label}",
                codepro_risk_tier_label(previous)
            )
        },
    );
    let now = Utc::now();
    CodeProAnalysisActivity {
        message: format!(
            "CodePro · {title}\n当前阶段：准备执行\n{level}\n流程：{flow}\n原因：{reasons}"
        ),
        event: Some(ActivityEvent {
            schema_version: ACTIVITY_EVENT_SCHEMA_VERSION,
            event_id: format!("execution-strategy-{:?}", plan.risk_tier).to_lowercase(),
            event_type: if previous_risk_tier.is_some() {
                ActivityEventKind::StrategyUpdated
            } else {
                ActivityEventKind::StrategySelected
            },
            session_id: session_id.to_string(),
            run_id: run_id.to_string(),
            task_id: None,
            parent_task_id: None,
            agent_role: None,
            effective_model: None,
            status: ActivityEventStatus::Completed,
            started_at: now,
            finished_at: Some(now),
            title: title.to_string(),
            technical_details: Some(format!("说明：{}", plan.strategy_zh)),
            path: None,
            command_summary: None,
            exit_code: None,
            diff_summary: None,
            failure_kind: None,
            risk_tier: Some(plan.risk_tier),
            previous_risk_tier,
            risk_reasons: plan.risk_reasons.clone(),
            selected_roles: plan.roles.clone(),
            review_required: Some(plan.review_required),
            routing_evidence: None,
            include_in_model_context: false,
            retryable: false,
            retry_from_event_id: None,
        }),
        test_progress: None,
        forwarded_message: None,
    }
}

fn codepro_read_only_goal_requires_execution_plan(goal: &str) -> bool {
    let normalized = goal.to_lowercase();
    let rejects_plan = [
        "不要生成执行计划",
        "不生成执行计划",
        "无需执行计划",
        "不需要执行计划",
        "不要规划",
        "无需规划",
        "no execution plan",
        "without an execution plan",
        "do not plan",
    ]
    .iter()
    .any(|marker| normalized.contains(marker));
    if rejects_plan {
        return false;
    }

    [
        "复杂任务",
        "复杂只读",
        "长任务",
        "多步骤",
        "多阶段",
        "分阶段",
        "执行计划",
        "制定计划",
        "规划下一步",
        "complex task",
        "multi-step",
        "multistep",
        "phased plan",
        "execution plan",
    ]
    .iter()
    .any(|marker| normalized.contains(marker))
}

fn codepro_task_requires_execution_plan(task_kind: CodeProTaskKind, goal: &str) -> bool {
    matches!(
        task_kind,
        CodeProTaskKind::ProjectTest | CodeProTaskKind::BugFix | CodeProTaskKind::ComplexChange
    ) || (task_kind == CodeProTaskKind::ReadOnly
        && codepro_read_only_goal_requires_execution_plan(goal))
}

fn codepro_thinking_decision(
    plan: &CodeProRolePlan,
    goal: &str,
    public_summary: Option<&str>,
) -> String {
    if plan.task_kind == CodeProTaskKind::ReadOnly
        && codepro_read_only_goal_requires_execution_plan(goal)
    {
        return format!(
            "用户希望“{}”。这是多步骤只读分析，我会先整理目标和约束，形成简短执行计划，再按计划取得必要证据；全程不修改文件。",
            codepro_goal_excerpt(goal)
        );
    }
    if let Some(summary) = public_summary
        .map(str::trim)
        .filter(|summary| !summary.is_empty())
    {
        return summary.to_string();
    }
    let next_action = match plan.task_kind {
        CodeProTaskKind::Conversation => "这个请求不需要项目证据或工具，最少完成动作是直接回复。",
        CodeProTaskKind::ReadOnly => {
            "这是只读问题，我会取得最少的必要证据后直接回答，不生成执行计划。"
        }
        CodeProTaskKind::ToolAction => {
            "这是工具操作任务，我会延续当前目标，调用已启用的共享工具，并核验实际结果。"
        }
        CodeProTaskKind::FocusedTest => {
            "测试目标已经明确，交给 Tester Agent 直接运行聚焦测试，不增加额外规划。"
        }
        CodeProTaskKind::SimpleChange => "修改目标和范围明确，我会直接完成最小范围修改并验证结果。",
        CodeProTaskKind::ProjectTest => {
            "这是项目级测试，需要先确定测试范围，再交给 Tester Agent 分阶段验证。"
        }
        CodeProTaskKind::BugFix => {
            "这是缺陷修复任务，需要先定位根因和影响范围，再由 Coder Agent 修复、Tester Agent 验证。"
        }
        CodeProTaskKind::ComplexChange => {
            "这是多步骤改动，需要先由 Planner Agent 拆分范围，再进入实施和独立验证。"
        }
    };
    format!("用户希望“{}”。{next_action}", codepro_goal_excerpt(goal))
}

fn codepro_thinking_summary(
    plan: &CodeProRolePlan,
    goal: &str,
    public_summary: Option<&str>,
) -> String {
    format!(
        "CodePro · 思考\n{}",
        codepro_thinking_decision(plan, goal, public_summary)
    )
}

