    pub async fn update_provider(
        &self,
        provider: Arc<dyn Provider>,
        model_config: goose_providers::model::ModelConfig,
        session_id: &str,
    ) -> Result<()> {
        let provider_name = provider.get_name().to_string();

        // Normalize against the provider entry so custom/declarative providers
        // backfill `context_limit` from their known models before the config is
        // persisted as the session source of truth; otherwise auto-compaction
        // would fall back to DEFAULT_CONTEXT_LIMIT.
        let model_config = match crate::providers::get_from_registry(&provider_name).await {
            Ok(entry) => entry
                .normalize_model_config(model_config.clone())
                .unwrap_or(model_config),
            Err(_) => model_config,
        };

        self.config
            .session_manager
            .clone()
            .update(session_id)
            .provider_name(&provider_name)
            .model_config(model_config)
            .apply()
            .await
            .context("Failed to persist provider config to session")?;

        *self.provider.lock().await = Some(provider);
        Ok(())
    }

    pub async fn update_goose_mode(&self, mode: GooseMode, session_id: &str) -> Result<()> {
        if let Some(provider) = self.provider.lock().await.as_ref() {
            provider
                .update_mode(session_id, mode)
                .await
                .map_err(|e| anyhow::anyhow!("Provider rejected mode update: {e}"))?;
        }
        self.config
            .session_manager
            .clone()
            .update(session_id)
            .goose_mode(mode)
            .apply()
            .await
            .context("Failed to persist goose_mode to session")?;
        *self.current_goose_mode.lock().await = mode;
        Ok(())
    }

    pub async fn goose_mode(&self) -> GooseMode {
        *self.current_goose_mode.lock().await
    }

    /// A delegated Agent cannot keep an older, more permissive mode after its
    /// parent session changes mode. The durable parent session is the source of
    /// that choice; a missing binding leaves the child unable to execute tools.
    pub(super) async fn permission_mode_for_scope(
        &self,
        scope: Option<&CodeProTaskScope>,
    ) -> GooseMode {
        let own_mode = self.goose_mode().await;
        let Some(scope) = scope.filter(|scope| scope.task_id() != "main-agent") else {
            return own_mode;
        };
        let Some(parent_session_id) = scope.permission_session_id() else {
            return GooseMode::Chat;
        };
        let parent_mode = match self
            .config
            .session_manager
            .get_session(parent_session_id, false)
            .await
        {
            Ok(parent) => parent.goose_mode,
            Err(error) => {
                tracing::warn!(parent_session_id, %error,
                    "delegated permission mode could not be read; denying tool execution");
                return GooseMode::Chat;
            }
        };
        match (own_mode, parent_mode) {
            (GooseMode::Chat, _) | (_, GooseMode::Chat) => GooseMode::Chat,
            (GooseMode::Approve, _) | (_, GooseMode::Approve) => GooseMode::Approve,
            (GooseMode::SmartApprove, _) | (_, GooseMode::SmartApprove) => GooseMode::SmartApprove,
            _ => GooseMode::Auto,
        }
    }

    pub async fn recreate_provider_for_session(
        &self,
        session_id: &str,
        provider_name: &str,
        model_config: goose_providers::model::ModelConfig,
    ) -> Result<()> {
        let session = self
            .config
            .session_manager
            .get_session(session_id, false)
            .await
            .context("Failed to get session")?;

        let extensions = EnabledExtensionsState::extensions_or_default(
            Some(&session.extension_data),
            Config::global(),
        );

        let provider = self
            .create_provider_for_working_dir(provider_name, extensions, session.working_dir.clone())
            .await
            .map_err(|e| anyhow!("Could not create provider: {}", e))?;

        let mode = self.goose_mode().await;
        provider
            .update_mode(session_id, mode)
            .await
            .map_err(|e| anyhow!("Provider rejected mode update: {e}"))?;
        self.update_provider(provider, model_config, session_id)
            .await
    }

    pub async fn update_thinking_effort(
        &self,
        session_id: &str,
        effort: ThinkingEffort,
    ) -> Result<()> {
        let current_provider = self.provider().await?;
        let provider_name = current_provider.get_name().to_string();
        let model_config = self
            .model_config_for_session(session_id)
            .await?
            .with_thinking_effort(effort);

        self.recreate_provider_for_session(session_id, &provider_name, model_config)
            .await
    }

    /// Restore the provider from session data or fall back to global config
    /// This is used when resuming a session to restore the provider state
    /// Returns true if the session's provider was replaced with a fallback.
    pub async fn restore_provider_from_session(&self, session: &Session) -> Result<bool> {
        let config = Config::global();

        let provider_name = session
            .provider_name
            .clone()
            .or_else(|| config.get_goose_provider().ok())
            .ok_or_else(|| anyhow!("Could not configure agent: missing provider"))?;

        let mut model_config = match session.model_config.clone() {
            Some(saved_config) => saved_config,
            None => {
                let model_name = config
                    .get_goose_model()
                    .ok()
                    .ok_or_else(|| anyhow!("Could not configure agent: missing model"))?;
                crate::model_config::model_config_from_user_config(&provider_name, &model_name)
                    .map_err(|e| anyhow!("Could not configure agent: invalid model {}", e))?
            }
        };

        // if the saved model is the ACP sentinel "current", only preserve this if the provider
        // uses this sentinel to indicate it's an ACP provider that manages its model
        if model_config.model_name == crate::acp::ACP_CURRENT_MODEL {
            if let Ok(entry) = crate::providers::get_from_registry(&provider_name).await {
                if entry.metadata().default_model != crate::acp::ACP_CURRENT_MODEL {
                    model_config = crate::model_config::model_config_from_user_config(
                        &provider_name,
                        &entry.metadata().default_model,
                    )
                    .map_err(|e| anyhow!("Could not resolve default model: {}", e))?;
                }
            }
        }

        let extensions =
            EnabledExtensionsState::extensions_or_default(Some(&session.extension_data), config);

        let provider_is_available = self.config.model_router_provider_factory.is_some()
            || crate::providers::get_from_registry(&provider_name)
                .await
                .is_ok();
        let (provider, active_model_config, provider_changed) = if provider_is_available {
            let p = self
                .create_provider_for_working_dir(
                    &provider_name,
                    extensions.clone(),
                    session.working_dir.clone(),
                )
                .await
                .map_err(|e| anyhow!("Could not create provider: {}", e))?;
            (p, model_config, false)
        } else {
            let fallback_provider_name = config
                .get_goose_provider()
                .ok()
                .filter(|name| name != &provider_name)
                .ok_or_else(|| {
                    anyhow!(
                        "Could not create provider: provider '{}' not found",
                        provider_name
                    )
                })?;

            tracing::warn!(
                "Session provider '{}' unavailable, falling back to '{}'",
                provider_name,
                fallback_provider_name
            );

            let fallback_model_name = config
                .get_goose_model()
                .ok()
                .ok_or_else(|| anyhow!("Could not configure fallback provider: missing model"))?;
            let fallback_model_config = crate::model_config::model_config_from_user_config(
                &fallback_provider_name,
                &fallback_model_name,
            )
            .map_err(|e| anyhow!("Could not configure fallback provider: invalid model {}", e))?;

            let fallback_provider = self
                .create_provider_for_working_dir(
                    &fallback_provider_name,
                    extensions,
                    session.working_dir.clone(),
                )
                .await
                .map_err(|e| {
                    anyhow!(
                        "Could not create provider '{}' or fallback '{}': {}",
                        provider_name,
                        fallback_provider_name,
                        e
                    )
                })?;

            if let Err(e) = self
                .config
                .session_manager
                .update(&session.id)
                .provider_name(&fallback_provider_name)
                .model_config(fallback_model_config.clone())
                .apply()
                .await
            {
                tracing::warn!("Failed to update session provider: {}", e);
            }

            (fallback_provider, fallback_model_config, true)
        };

        self.update_provider(provider, active_model_config, &session.id)
            .await?;
        // Propagate session mode to the new provider
        if let Some(provider) = self.provider.lock().await.as_ref() {
            provider
                .update_mode(&session.id, session.goose_mode)
                .await
                .map_err(|e| anyhow!("Failed to propagate mode to provider: {}", e))?;
        }
        *self.current_goose_mode.lock().await = session.goose_mode;
        Ok(provider_changed)
    }

    async fn create_provider_for_working_dir(
        &self,
        provider_name: &str,
        extensions: Vec<ExtensionConfig>,
        working_dir: PathBuf,
    ) -> Result<Arc<dyn Provider>> {
        match self.config.model_router_provider_factory.as_ref() {
            Some(factory) => {
                factory(provider_name.to_string(), extensions, Some(working_dir)).await
            }
            None => {
                crate::providers::create_with_working_dir(provider_name, extensions, working_dir)
                    .await
            }
        }
    }

