    #[test]
    fn ask_user_flow_unanswered_business_question_cannot_be_mistaken_for_other_tool_output() {
        let request = ToolRequest {
            id: "question-1".to_string(),
            tool_call: Ok(CallToolRequestParams::new("developer__ask_user")),
            metadata: None,
            tool_meta: None,
        };
        let unanswered = Ok(CallToolResult::success(vec![Content::text(
            r#"{"action":"unanswered","reason":"cancelled_or_expired"}"#,
        )]));
        assert!(codepro_unanswered_question_result(&request, &unanswered));

        let answered = Ok(CallToolResult::success(vec![Content::text(
            r#"{"action":"accept","answers":{"behavior":"keep"}}"#,
        )]));
        assert!(!codepro_unanswered_question_result(&request, &answered));

        let other_tool = ToolRequest {
            tool_call: Ok(CallToolRequestParams::new("developer__read_document")),
            ..request
        };
        assert!(!codepro_unanswered_question_result(
            &other_tool,
            &unanswered
        ));
    }

    #[test]
    fn ask_user_flow_unanswered_question_does_not_suppress_independent_file_reads() {
        let tools = crate::agents::platform_extensions::developer::DeveloperClient::get_tools();
        let request = |name: &str| ToolRequest {
            id: name.to_string(),
            tool_call: Ok(CallToolRequestParams::new(name.to_string())),
            metadata: None,
            tool_meta: None,
        };

        assert!(codepro_question_allows_independent_read(
            &request("read_document"),
            &tools
        ));
        assert!(!codepro_question_allows_independent_read(
            &request("write"),
            &tools
        ));
        assert!(!codepro_question_allows_independent_read(
            &request("shell"),
            &tools
        ));
    }

    #[test]
