    struct CoverageThenAnswerProvider {
        calls: std::sync::atomic::AtomicUsize,
        runtime: CodeProRuntime,
        session_id: String,
        run_id: RunId,
        illegal_answer_call: bool,
        answer_error: bool,
    }

    #[async_trait::async_trait]
    impl crate::providers::base::Provider for CoverageThenAnswerProvider {
        async fn stream(
            &self,
            _config: &goose_providers::model::ModelConfig,
            _prompt: &str,
            messages: &[Message],
            tools: &[Tool],
        ) -> Result<MessageStream, ProviderError> {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            let coverage = || {
                CallToolRequestParams::new(super::super::main_agent_contract::TOOL_NAME)
                .with_arguments(serde_json::json!({"operation":"propose_coverage", "requirement_revision":1,
                    "summary":"The fixture was read.", "coverage":[{"requirement_id":"read", "audit_ids":["read-audit"]}]}).as_object().unwrap().clone())
            };
            let usage = ProviderUsage::new("fixture".into(), Usage::default());
            match call {
                0 => Ok(stream_from_single_message(
                    Message::assistant()
                        .with_tool_request("coverage-mixed", Ok(coverage()))
                        .with_tool_request(
                            "progress-mixed",
                            Ok(CallToolRequestParams::new(
                                super::super::main_agent_contract::PROGRESS_TOOL_NAME,
                            )
                            .with_arguments(
                                serde_json::json!({"text":"This sibling must not publish."})
                                    .as_object()
                                    .unwrap()
                                    .clone(),
                            )),
                        ),
                    usage,
                )),
                1 => {
                    let results = messages
                        .iter()
                        .flat_map(|m| &m.content)
                        .filter_map(|c| match c {
                            MessageContent::ToolResponse(response)
                                if ["coverage-mixed", "progress-mixed"]
                                    .contains(&response.id.as_str()) =>
                            {
                                Some(response)
                            }
                            _ => None,
                        })
                        .collect::<Vec<_>>();
                    assert_eq!(results.len(), 2);
                    assert!(results
                        .iter()
                        .all(|r| r.tool_result.as_ref().unwrap().is_error == Some(true)));
                    assert_eq!(
                        self.runtime
                            .snapshot(&self.session_id, &self.run_id)
                            .await
                            .unwrap()
                            .projection
                            .state,
                        RunState::Running
                    );
                    Ok(stream_from_single_message(
                        Message::assistant().with_tool_request("coverage-valid", Ok(coverage())),
                        usage,
                    ))
                }
                2 => {
                    assert!(
                        tools.is_empty(),
                        "accepted execution must not offer tools to the answer; receipts: {:?}",
                        messages.iter().flat_map(|m| &m.content).filter(|c| matches!(c, MessageContent::ToolResponse(r) if r.id == "coverage-valid")).collect::<Vec<_>>()
                    );
                    assert_eq!(
                        self.runtime
                            .snapshot(&self.session_id, &self.run_id)
                            .await
                            .unwrap()
                            .projection
                            .state,
                        RunState::Completed
                    );
                    let illegal = self.illegal_answer_call;
                    let answer_error = self.answer_error;
                    Ok(Box::pin(async_stream::stream! {
                        yield Ok((Some(Message::assistant().with_text("RESULT-FIRST.")), Some(usage)));
                        if answer_error {
                            yield Err(ProviderError::NetworkError("isolated answer stream interruption".into()));
                            return;
                        }
                        yield Ok((Some(Message::assistant().with_text("RESULT-LAST.")), None));
                        if illegal {
                            yield Ok((Some(Message::assistant().with_tool_request("answer-call", Ok(CallToolRequestParams::new(super::super::main_agent_contract::PROGRESS_TOOL_NAME)
                                .with_arguments(serde_json::json!({"text":"This answer call must not publish."}).as_object().unwrap().clone())))), None));
                        }
                    }))
                }
                _ => panic!("answer must not reopen execution or recheck completion"),
            }
        }
        fn get_name(&self) -> &str {
            "coverage-answer-fixture"
        }
    }

    #[tokio::test]
    async fn completion_storage_fault_is_not_a_model_repair_gap_and_healthy_storage_completes(
    ) -> Result<()> {
        use crate::agents::tool_audit::{
            ToolAuditActor, ToolAuditAuthorization, ToolAuditExtensionSource, ToolAuditOutcome,
            ToolAuditPermissionClass, ToolAuditReceipt,
        };
        use crate::conversation::message::ToolResponse;
        for fault in [
            "aggregated-gaps",
            "healthy",
            "healthy-answer-tool",
            "healthy-answer-error",
            "artifact-directory-is-file",
            "invalid-event-log",
            "missing-store",
        ] {
            let temp = tempfile::tempdir()?;
            let manager = Arc::new(SessionManager::new(temp.path().join("sessions")));
            let runtime = CodeProRuntime::initialize_production(
                temp.path().join("runtime"),
                crate::agents::control_plane::RuntimeModePolicy::parse(Some("durable")),
            )
            .await?;
            let mut session = manager
                .create_session(
                    temp.path().to_path_buf(),
                    "completion storage fixture".into(),
                    SessionType::CodePro,
                    GooseMode::Auto,
                )
                .await?;
            bind_test_workspace(&manager, &mut session).await?;
            let agent = Agent::with_config(
                AgentConfig::new(
                    manager.clone(),
                    Arc::new(PermissionManager::new(temp.path().join("permissions"))),
                    None,
                    GooseMode::Auto,
                    true,
                    GoosePlatform::GooseCli,
                )
                .with_codepro_runtime(runtime.clone())
                .with_codepro_event_log_root(temp.path().join("stream-events")),
            );
            let control_task = MainAgentControlTask {
                run_id: RunId::new("storage-fixture")?,
                task_id: TaskId::new("main-agent")?,
            };
            runtime
                .create_or_verify_run(&session.id, control_task.run_id.clone(), "read the fixture")
                .await?;
            runtime.control(&session.id, ControlCommand::CommitUserRequirements {
                run_id: control_task.run_id.clone(), revision: 1,
                requirements: vec![serde_json::from_value(serde_json::json!({
                    "requirement_id":"read", "source_message_id":"user",
                    "semantics":{"content":"read the fixture", "expected_effect":"observation", "target_resources":[]}
                }))?],
            }, None).await?;
            agent
                .prepare_main_agent_control_task(
                    &session.id,
                    &control_task,
                    CodeProTaskKind::ToolAction,
                )
                .await?;
            let input_path = temp.path().join("input.txt");
            std::fs::write(&input_path, "fixture content")?;
            let request = ToolRequest {
                id: "read-call".into(),
                tool_call: Ok(CallToolRequestParams::new("developer__read_document")
                    .with_arguments(
                        serde_json::json!({"path":input_path})
                            .as_object()
                            .unwrap()
                            .clone(),
                    )),
                metadata: None,
                tool_meta: None,
            };
            let now = chrono::Utc::now();
            let mut receipt = ToolAuditReceipt {
                schema_version: 2,
                audit_id: "read-audit".into(),
                actor: ToolAuditActor::Primary,
                effective_model: "test/model".into(),
                extension_source: ToolAuditExtensionSource::Platform,
                tool_name: "developer::read_document".into(),
                permission_class: ToolAuditPermissionClass::ReadOnly,
                authorization: ToolAuditAuthorization::PolicyAllowed,
                outcome: ToolAuditOutcome::Success,
                failure_kind: None,
                task_scoped: false,
                task_scope_digest: None,
                started_at: now,
                completed_at: now,
                duration_ms: 1,
            };
            let mut result =
                CallToolResult::success(vec![Content::text(std::fs::read_to_string(&input_path)?)]);
            insert_trusted_tool_audit_meta(&mut result, &receipt);
            let response = ToolResponse {
                id: "read-call".into(),
                tool_result: Ok(result.clone()),
                metadata: None,
            };
            let mut progress = super::super::tool_task::ToolTaskProgress::default();
            progress.observe(&request, &response);
            let coverage = super::super::main_agent_contract::CoverageProposal {
                requirement_revision: 1,
                coverage: vec![serde_json::from_value(serde_json::json!({
                    "requirement_id":"read", "audit_ids":["read-audit"]
                }))?],
            };
            let event_path = temp.path().join("activity/events.jsonl");
            let event_log = Some(Arc::new(StdMutex::new(Some(CodeProEventLog::open(
                &event_path,
            )?))));
            if fault == "aggregated-gaps" {
                use crate::agents::protocol::PlannedTask;
                let child_id = TaskId::new("unfinished-child")?;
                let existing_main = runtime
                    .snapshot(&session.id, &control_task.run_id)
                    .await?
                    .projection
                    .tasks[&control_task.task_id]
                    .clone();
                runtime
                    .install_plan(
                        &session.id,
                        control_task.run_id.clone(),
                        2,
                        vec![
                            PlannedTask {
                                task_id: control_task.task_id.clone(),
                                name: existing_main.name,
                                role: existing_main.role,
                                depends_on: vec![],
                            },
                            PlannedTask {
                                task_id: child_id.clone(),
                                name: "Child".into(),
                                role: None,
                                depends_on: vec![],
                            },
                        ],
                    )
                    .await?;
                runtime
                    .start_task(&session.id, control_task.run_id.clone(), child_id.clone())
                    .await?;
                runtime
                    .submit_inline_outcome(
                        &session.id,
                        control_task.run_id.clone(),
                        child_id,
                        crate::agents::protocol::WorkerOutcome::Paused(
                            crate::agents::protocol::Checkpoint {
                                checkpoint_id: "partial".into(),
                                summary: "budget exhausted".into(),
                                evidence_refs: vec![],
                            },
                        ),
                    )
                    .await?;
                // Two file targets and a paused child already exist at one boundary.
                // No fresh semantic interpretation is needed to report them together.
                let mut requirement = runtime
                    .snapshot(&session.id, &control_task.run_id)
                    .await?
                    .projection
                    .user_requirements["read"]
                    .clone();
                let semantics = requirement.semantics.as_mut().unwrap();
                semantics.expected_effect =
                    Some(crate::agents::protocol::RequirementEffect::WorkspaceChange);
                semantics.target_resources = vec!["missing-a.txt".into(), "missing-b.txt".into()];
                semantics.revision_relation =
                    Some(crate::agents::protocol::RequirementRevisionRelation {
                        previous_revision: 1,
                        requirement_ids: vec!["read".into()],
                        kind: crate::agents::protocol::RequirementRevisionKind::Replaced,
                    });
                runtime
                    .control(
                        &session.id,
                        ControlCommand::CommitUserRequirements {
                            run_id: control_task.run_id.clone(),
                            revision: 2,
                            requirements: vec![requirement],
                        },
                        None,
                    )
                    .await?;
                let mut current_coverage = coverage.clone();
                current_coverage.requirement_revision = 2;
                let before = runtime.snapshot(&session.id, &control_task.run_id).await?;
                let attempt = agent
                    .propose_main_agent_finish(
                        &session.id,
                        &control_task,
                        CodeProTaskKind::ToolAction,
                        "deliver",
                        (&progress, None),
                        Some(&current_coverage),
                        &event_log,
                    )
                    .await?;
                let MainAgentCompletionAttempt::Rejected(gaps) = attempt else {
                    panic!("unfinished work accepted or misclassified")
                };
                let joined = gaps.join("\n");
                for expected in ["missing-a.txt", "missing-b.txt", "unfinished-child"] {
                    assert!(joined.contains(expected), "missing {expected}: {joined}");
                }
                assert_eq!(
                    runtime
                        .snapshot(&session.id, &control_task.run_id)
                        .await?
                        .projection
                        .last_sequence,
                    before.projection.last_sequence,
                    "preflight must not mutate task lifecycle"
                );
                assert!(
                    event_log
                        .as_ref()
                        .unwrap()
                        .lock()
                        .unwrap()
                        .as_ref()
                        .unwrap()
                        .records()
                        .is_empty(),
                    "rejected preflight must not commit completion evidence"
                );
                continue;
            }
            match fault {
                "artifact-directory-is-file" => {
                    std::fs::write(temp.path().join("activity/artifacts"), "not a directory")?
                }
                "invalid-event-log" => std::fs::write(&event_path, "not a valid event\n")?,
                "missing-store" => *event_log.as_ref().unwrap().lock().unwrap() = None,
                _ => {}
            }
            // Business gaps and Unknown must still be rejected before storage handling.
            assert!(matches!(
                agent
                    .propose_main_agent_finish(
                        &session.id,
                        &control_task,
                        CodeProTaskKind::ToolAction,
                        "read",
                        (&progress, None),
                        None,
                        &event_log,
                    )
                    .await?,
                MainAgentCompletionAttempt::Rejected(_)
            ));
            receipt.outcome = ToolAuditOutcome::Ambiguous;
            receipt.audit_id = "uncertain-audit".into();
            insert_trusted_tool_audit_meta(&mut result, &receipt);
            let mut unknown = super::super::tool_task::ToolTaskProgress::default();
            unknown.observe(&request, &response);
            let mut uncertain_request = request.clone();
            uncertain_request.id = "uncertain-call".into();
            unknown.observe(
                &uncertain_request,
                &ToolResponse {
                    id: "uncertain-call".into(),
                    tool_result: Ok(result.clone()),
                    metadata: None,
                },
            );
            assert_eq!(unknown.unresolved_action_count(), 1);
            assert!(matches!(
                agent
                    .propose_main_agent_finish(
                        &session.id,
                        &control_task,
                        CodeProTaskKind::ToolAction,
                        "read",
                        (&unknown, None),
                        Some(&coverage),
                        &event_log,
                    )
                    .await?,
                MainAgentCompletionAttempt::Rejected(gaps) if gaps.iter().any(|gap| gap.contains("uncertain-call"))
            ));
            let before = runtime.snapshot(&session.id, &control_task.run_id).await?;
            let attempt = if fault.starts_with("healthy") {
                let scope = CodeProTaskScope::new_bound(
                    control_task.run_id.as_str(),
                    control_task.task_id.as_str(),
                    temp.path().canonicalize()?,
                    vec!["**".into()],
                    Vec::new(),
                )
                .and_then(|scope| scope.with_permission_session_id(&session.id))
                .map_err(anyhow::Error::msg)?;
                let mut scoped_receipt = receipt.clone();
                scoped_receipt.audit_id = "read-audit".into();
                scoped_receipt.outcome = ToolAuditOutcome::Success;
                scoped_receipt.task_scoped = true;
                scoped_receipt.task_scope_digest =
                    Some(crate::agents::tool_audit::task_scope_digest(&scope));
                let mut scoped_result = result.clone();
                insert_trusted_tool_audit_meta(&mut scoped_result, &scoped_receipt);
                session.conversation = Some(Conversation::new_unvalidated(vec![
                    Message::user()
                        .with_id("fixture-start")
                        .with_text("read the fixture"),
                    Message::assistant()
                        .with_generated_id()
                        .with_tool_request("read-call", request.tool_call.clone()),
                    Message::user()
                        .with_generated_id()
                        .with_tool_response("read-call", Ok(scoped_result)),
                ]));
                let provider = Arc::new(CoverageThenAnswerProvider {
                    calls: std::sync::atomic::AtomicUsize::new(0),
                    runtime: runtime.clone(),
                    session_id: session.id.clone(),
                    run_id: control_task.run_id.clone(),
                    illegal_answer_call: fault == "healthy-answer-tool",
                    answer_error: fault == "healthy-answer-error",
                });
                agent
                    .update_provider(
                        provider.clone(),
                        goose_providers::model::ModelConfig::new("fixture"),
                        &session.id,
                    )
                    .await?;
                let mut options =
                    UnifiedExecutorOptions::codepro_main_agent(CodeProTaskKind::ToolAction)
                        .with_main_agent_control_run(control_task.run_id.clone())?;
                options.permission_scope = Some(scope);
                let mut events = agent
                    .reply_codepro_unified(
                        &session,
                        Message::user()
                            .with_id("user")
                            .with_text("read the fixture"),
                        SessionConfig {
                            id: session.id.clone(),
                            schedule_id: None,
                            max_turns: Some(10),
                            retry_config: None,
                        },
                        None,
                        options,
                    )
                    .await?;
                let mut boundary_seen = false;
                let mut text = String::new();
                let mut terminal_seen = false;
                while let Some(event) =
                    tokio::time::timeout(std::time::Duration::from_secs(20), events.next()).await?
                {
                    if let AgentEvent::Message(message) = event? {
                        for content in &message.content {
                            match content {
                                MessageContent::SystemNotification(notification)
                                    if notification.data.as_ref().is_some_and(|data| {
                                        data["type"] == "codepro_response_phase"
                                    }) =>
                                {
                                    boundary_seen = true
                                }
                                MessageContent::SystemNotification(notification)
                                    if notification.notification_type
                                        == SystemNotificationType::TurnTerminal =>
                                {
                                    assert!(text.contains("RESULT-FIRST."));
                                    if fault != "healthy-answer-error" {
                                        assert!(text.contains("RESULT-FIRST.RESULT-LAST."));
                                    }
                                    terminal_seen = true;
                                }
                                MessageContent::Text(part)
                                    if message.metadata.user_visible
                                        && part.text.starts_with("RESULT-") =>
                                {
                                    assert!(
                                        boundary_seen,
                                        "formal answer streamed before its boundary"
                                    );
                                    assert!(
                                        !terminal_seen,
                                        "terminal sealed the stream before the last token"
                                    );
                                    text.push_str(&part.text);
                                    if part.text == "RESULT-FIRST." {
                                        assert!(agent.steer_codepro_run(&session.id, control_task.run_id.as_str(), Message::user().with_text("交付说明之后再讨论一个新问题，不要暗中继续执行旧任务")).await.is_err());
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
                assert!(boundary_seen && terminal_seen);
                assert!(
                    !agent.has_pending_steers(&session.id).await,
                    "answering must reject steering admission so the caller retains its queued input"
                );
                assert_eq!(provider.calls.load(Ordering::SeqCst), 3);
                let saved = manager.get_session(&session.id, true).await?;
                let history = saved.conversation.as_ref().unwrap().messages();
                assert!(history.iter().flat_map(|m| &m.content).any(|c| matches!(c, MessageContent::SystemNotification(n) if n.data.as_ref().is_some_and(|data| data["type"] == "codepro_response_phase"))));
                if fault == "healthy-answer-tool" {
                    assert!(history.iter().flat_map(|m| &m.content).any(|c| matches!(c, MessageContent::ToolResponse(r) if r.id == "answer-call" && r.tool_result.as_ref().is_ok_and(|result| result.is_error == Some(true)))));
                }
                if fault == "healthy-answer-error" {
                    assert!(history
                        .iter()
                        .any(|m| m.as_concat_text().contains("未能完整生成")
                            || m.as_concat_text().contains("could not finish")));
                    assert!(history
                        .iter()
                        .any(|m| m.as_concat_text().contains("RESULT-FIRST.")));
                }
                MainAgentCompletionAttempt::Completed
            } else {
                agent
                    .propose_main_agent_finish(
                        &session.id,
                        &control_task,
                        CodeProTaskKind::ToolAction,
                        "read",
                        (&progress, None),
                        Some(&coverage),
                        &event_log,
                    )
                    .await?
            };
            if fault.starts_with("healthy") {
                assert!(matches!(attempt, MainAgentCompletionAttempt::Completed));
                assert_eq!(
                    runtime
                        .snapshot(&session.id, &control_task.run_id)
                        .await?
                        .projection
                        .state,
                    RunState::Completed
                );
            } else {
                assert!(
                    matches!(attempt, MainAgentCompletionAttempt::HostEvidenceUnavailable),
                    "{fault}"
                );
                let after = runtime.snapshot(&session.id, &control_task.run_id).await?;
                assert_eq!(
                    after.projection.last_sequence,
                    before.projection.last_sequence
                );
                assert_eq!(std::fs::read_to_string(&input_path)?, "fixture content");
                agent
                    .finalize_main_agent_control_task(
                        &session.id,
                        &control_task,
                        Some("execution_error"),
                        false,
                    )
                    .await?;
                assert_eq!(
                    runtime
                        .snapshot(&session.id, &control_task.run_id)
                        .await?
                        .projection
                        .state,
                    RunState::Paused
                );
            }
        }
        Ok(())
    }

    #[tokio::test]
