    #[test]
    fn locale_policy_survives_context_refresh_without_a_synthetic_user_turn() {
        for locale in [Some("zh-CN"), Some("zh-TW"), Some("en-US"), None] {
            let mut system = "existing system rules".to_owned();
            let mut addendum = "existing context".to_owned();
            append_locale_system_instruction(&mut system, &mut addendum, locale);
            if let Some(policy) = locale_output_instruction(locale) {
                // Both initial context and a rebuilt prompt retain the language policy.
                assert_eq!(system, format!("existing system rules\n\n{policy}"));
                assert_eq!(addendum, format!("existing context\n\n{policy}"));
            } else {
                assert_eq!(system, "existing system rules");
                assert_eq!(addendum, "existing context");
            }
        }
    }

    #[test]
    fn explicit_no_tools_instruction_forces_a_direct_conversation_turn() {
        let original_prompt = "不要调用任何工具，不要搜索，不要执行计划。只回复“跨项目测试”，并遵守你已经记住的用户表达偏好。";
        eprintln!("explicit no-tools exact prompt: {original_prompt}");
        for goal in [
            "没有信息就说不知道，不要调用工具。",
            "请直接回答，不使用任何工具。",
            "Reply directly without using tools.",
            original_prompt,
        ] {
            assert!(explicitly_forbids_tool_use(goal), "{goal}");
        }
        assert!(!explicitly_forbids_tool_use("请调用记忆工具保存这个规则"));
        assert_eq!(
            explicit_literal_reply("如果不知道，只回复“不知道”"),
            Some("不知道".to_string())
        );
        assert_eq!(
            explicit_literal_reply("Only reply \"unknown\"."),
            Some("unknown".to_string())
        );
        assert_eq!(explicit_literal_reply("只回复代号"), None);
        assert_eq!(
            enforceable_literal_reply("不要调用工具，只回复“不知道”"),
            Some("不知道".to_string())
        );
        assert_eq!(
            enforceable_literal_reply("只回复“完成”，不要搜索，也不要执行计划。"),
            Some("完成".to_string())
        );
        assert_eq!(enforceable_literal_reply(original_prompt), None);
        assert_eq!(
            enforceable_literal_reply("只回复“完成”，并在末尾附上日期。"),
            None
        );
        assert_eq!(
            enforceable_literal_reply("只回复“完成”，并使用 Markdown 格式。"),
            None
        );
        assert_eq!(
            enforceable_literal_reply(
                "Only reply \"Done\", and follow the remembered response preferences."
            ),
            None
        );

        let conversation = Conversation::new_unvalidated(vec![
            Message::user().with_text("不要调用工具，只回复“不知道”")
        ]);
        let mut options = UnifiedExecutorOptions::codepro_project_memory_management();
        assert!(apply_explicit_no_tools_constraint(
            &conversation,
            &mut options
        ));
        assert!(options.conversation_only);
        assert!(options.explicit_no_tools);
        assert_eq!(options.exact_reply, Some("不知道".to_string()));
        assert!(!options.project_memory_management);
        assert!(options.simple_change.is_none());

        let conversation =
            Conversation::new_unvalidated(vec![Message::user().with_text(original_prompt)]);
        let mut options = UnifiedExecutorOptions::codepro_analysis();
        assert!(apply_explicit_no_tools_constraint(
            &conversation,
            &mut options
        ));
        assert!(options.conversation_only);
        assert!(options.explicit_no_tools);
        assert_eq!(options.exact_reply, None);
        assert_eq!(options.task_kind, Some(CodeProTaskKind::Conversation));
        assert!(!options.uses_main_agent_completion());
    }

