            serde_json::from_str(visible.lines().nth(1).expect("serialized routing context"))
                .unwrap();
        assert_eq!(context["current_user_message"], "用电脑控制帮我完成");
        assert_eq!(context["prior_conversation"][0]["role"], "user");
