    #[test]
    fn text_only_model_context_preserves_user_images_and_filters_tool_images() {
        let messages = vec![
            Message::user().with_image("standalone-image", "image/png"),
            Message::user().with_tool_response(
                "computer-screenshot",
                Ok(CallToolResult::success(vec![
                    Content::text("screenshot evidence persisted"),
                    Content::image("tool-image", "image/png"),
                ])),
            ),
        ];

        let sanitized = model_context_without_unsupported_images(&messages, false);

        assert!(matches!(messages[0].content[0], MessageContent::Image(_)));
        assert_eq!(sanitized[0], messages[0]);
        let MessageContent::ToolResponse(original_tool) = &messages[1].content[0] else {
            panic!("original tool response");
        };
        assert!(original_tool
            .tool_result
            .as_ref()
            .unwrap()
            .content
            .iter()
            .any(|content| matches!(&content.raw, rmcp::model::RawContent::Image(_))));
        let MessageContent::ToolResponse(sanitized_tool) = &sanitized[1].content[0] else {
            panic!("sanitized tool response");
        };
        assert!(!sanitized_tool
            .tool_result
            .as_ref()
            .unwrap()
            .content
            .iter()
            .any(|content| matches!(&content.raw, rmcp::model::RawContent::Image(_))));
        assert_eq!(
            model_context_without_unsupported_images(&messages, true),
            messages
        );
    }
    #[test]
