    #[tokio::test]
    async fn vision_configuration_pauses_executor_after_image_rejection() -> Result<()> {
        #[derive(Debug, Default)]
        struct RejectImages(AtomicUsize);
        #[async_trait::async_trait]
        impl Provider for RejectImages {
            fn get_name(&self) -> &str {
                "image-rejection-fixture"
            }
            async fn stream(
                &self,
                _: &goose_providers::model::ModelConfig,
                _: &str,
                _: &[Message],
                _: &[Tool],
            ) -> Result<MessageStream, ProviderError> {
                self.0.fetch_add(1, Ordering::SeqCst);
                Err(ProviderError::RequestFailed(
                    "model does not support image input".into(),
                ))
            }
        }
        use goose_sdk_types::custom_requests::{
            CodeProModelRoutingConfig, CODEPRO_MODEL_ROUTING_CONFIG_KEY,
        };
        let values = HashMap::from([(
            CODEPRO_MODEL_ROUTING_CONFIG_KEY.into(),
            serde_json::to_value(CodeProModelRoutingConfig::default())?,
        )]);
        crate::config::base::with_candidate_provider_values(values, async {
            let data = tempfile::tempdir()?;
            let provider = Arc::new(RejectImages::default());
            let (agent, session_id) = create_test_agent(data.path().into(), crate::hooks::HookManager::from_plugins_for_test(vec![]), provider.clone()).await?;
            let mut reply = agent.reply(
                Message::user().with_text("Describe this image").with_image("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a7WQAAAAASUVORK5CYII=", "image/png"),
                SessionConfig { id: session_id.clone(), schedule_id: None, max_turns: Some(5), retry_config: None }, None,
            ).await?;
            let mut question_id = None;
            while let Some(event) = reply.next().await {
                if let AgentEvent::Message(message) = event? {
                    for content in message.content {
                        if let MessageContent::ActionRequired(required) = content {
                            if let ActionRequiredData::Elicitation { id, requested_schema, .. } = required.data {
                                assert_eq!(requested_schema["properties"]["next_step"]["oneOf"].as_array().unwrap().len(), 3);
                                question_id = Some(id);
                            }
                        }
                    }
                }
                if question_id.is_some() { break; }
            }
            let id = question_id.context("host must publish a user question")?;
            assert_eq!(provider.0.load(Ordering::SeqCst), 1);
            assert!(tokio::time::timeout(std::time::Duration::from_millis(50), reply.next()).await.is_err());
            assert_eq!(provider.0.load(Ordering::SeqCst), 1, "waiting must not issue another model request");
            crate::action_required_manager::ActionRequiredManager::global().claim_response(&session_id, &id).await?
                .submit(ElicitationOutcome::Accept(serde_json::json!({"next_step":"switch_model"})))?;
            while let Some(event) = reply.next().await { event?; }
            assert_eq!(provider.0.load(Ordering::SeqCst), 1, "configuration choice is not permission to continue with the old model");
            let saved = agent.config.session_manager.get_session(&session_id, true).await?;
            assert!(saved.conversation.unwrap().messages().iter().any(|message| message.content.iter().any(|item| matches!(item, MessageContent::ActionRequired(_)))));
            Ok::<_, anyhow::Error>(())
        }).await
    }

    #[tokio::test]
    async fn vision_configuration_cancellation_closes_pending_question() -> Result<()> {
        let token = CancellationToken::new();
        let session = format!("vision-cancel-{}", Uuid::new_v4());
        let mut questions = vision_configuration_pause(
            super::super::vision_service::VisionServiceError::Disabled,
            session.clone(),
            Some(token.clone()),
            true,
        );
        let message = questions.next().await.context("question")??;
        let MessageContent::ActionRequired(required) = &message.content[0] else {
            panic!("question expected")
        };
        let ActionRequiredData::Elicitation { id, .. } = &required.data else {
            panic!("elicitation expected")
        };
        token.cancel();
        assert!(questions.next().await.is_none());
        assert!(
            crate::action_required_manager::ActionRequiredManager::global()
                .claim_response(&session, id)
                .await
                .is_err()
        );
        Ok(())
    }

