    fn append_local_codepro_event(root: &Path, run_id: &str) {
        let event_path = root.join(run_id).join("run").join("events.jsonl");
        let mut log = CodeProEventLog::open(&event_path).unwrap();
        let now = chrono::Utc::now();
        log.append(
            &ActivityEvent {
                schema_version: ACTIVITY_EVENT_SCHEMA_VERSION,
                event_id: "approval-requested".to_string(),
                event_type: ActivityEventKind::ApprovalRequested,
                session_id: "session-1".to_string(),
                run_id: run_id.to_string(),
                task_id: Some("task-1".to_string()),
                parent_task_id: None,
                agent_role: Some(AgentRole::Tester),
                effective_model: None,
                status: ActivityEventStatus::Completed,
                started_at: now,
                finished_at: Some(now),
                title: "approval".to_string(),
                technical_details: None,
                path: None,
                command_summary: None,
                exit_code: None,
                diff_summary: None,
                failure_kind: None,
                risk_tier: None,
                previous_risk_tier: None,
                risk_reasons: Vec::new(),
                selected_roles: Vec::new(),
                review_required: None,
                routing_evidence: None,
                include_in_model_context: false,
                retryable: true,
                retry_from_event_id: None,
            },
            None,
        )
        .unwrap();
    }

