    #[async_trait::async_trait]
    impl goose_providers::retry::HttpAttemptGate for AllowTestHttpAttemptGate {
        async fn reserve_attempt(&self) -> Result<(), goose_providers::errors::ProviderError> {
            Ok(())
        }
    }

    #[async_trait::async_trait]
    impl goose_providers::retry::HttpAttemptGate for CountingTestHttpAttemptGate {
        async fn reserve_attempt(&self) -> Result<(), goose_providers::errors::ProviderError> {
            self.used.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }
    }

    #[tokio::test]
    async fn spawned_codepro_background_http_is_counted_before_physical_send() {
        let gate = Arc::new(CountingTestHttpAttemptGate::default());
        let physical_requests = Arc::new(AtomicUsize::new(0));
        let requests_for_task = Arc::clone(&physical_requests);

        spawn_codepro_http_task(Some(gate.clone()), async move {
            goose_providers::retry::reserve_http_attempt()
                .await
                .expect("the durable reservation should succeed");
            requests_for_task.fetch_add(1, Ordering::SeqCst);
        })
        .await
        .expect("the background task should finish");

        assert_eq!(physical_requests.load(Ordering::SeqCst), 1);
        assert_eq!(gate.used.load(Ordering::SeqCst), 1);
    }

