    #[test]
    fn provider_preflight_precedes_hooks_commands_and_prompt_persistence() {
        let source = include_str!("agent.rs").replace("\r\n", "\n");
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("agent test module boundary");
        let reply = production
            .split_once("pub async fn reply(")
            .and_then(|(_, tail)| tail.split_once("async fn reply_codepro_failed_validation_retry"))
            .map(|(reply, _)| reply)
            .expect("reply implementation boundary");
        let preflight = reply
            .find("validate_provider_credentials_before_run")
            .expect("provider preflight");
        let provider_free = reply
            .find("command_is_provider_free")
            .expect("provider-free classification");
        let local_command = reply
            .find("execute_command(&message_text")
            .expect("provider-free local command");
        assert!(provider_free < local_command && local_command < preflight);

        for side_effect in [
            "HookEvent::SessionStart",
            "HookEvent::UserPromptSubmit",
            "execute_command_with_prevalidated_provider",
        ] {
            assert!(
                preflight < reply.find(side_effect).expect("side effect marker"),
                "provider preflight must precede {side_effect}"
            );
        }
        let persisted_prompts = reply
            .match_indices("add_message(&session_config.id, &user_message)")
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        assert_eq!(persisted_prompts.len(), 2);
        assert!(
            persisted_prompts[0] < preflight && preflight < persisted_prompts[1],
            "only a non-agent-visible local message may persist without provider preflight"
        );
    }

    #[test]
    fn codepro_route_preflight_precedes_normal_prompt_persistence() {
        let source = include_str!("agent.rs").replace("\r\n", "\n");
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("agent test module boundary");
        let codepro = production
            .split_once("async fn reply_codepro_with_resume_inner")
            .and_then(|(_, tail)| tail.split_once("async fn reply_codepro_with_intent"))
            .map(|(codepro, _)| codepro)
            .expect("CodePro entrypoint boundary");
        let preflight = codepro
            .find("preflight_codepro_provider_routes")
            .expect("CodePro route preflight");
        let persisted_prompts = codepro
            .match_indices("add_message(&session_config.id, &user_message)")
            .map(|(index, _)| index)
            .collect::<Vec<_>>();

        assert_eq!(persisted_prompts.len(), 3);
        assert!(
            persisted_prompts[0] < preflight
                && persisted_prompts[1] < preflight
                && preflight < persisted_prompts[2],
            "only local failed-validation retry and blocked legacy resume may persist without advanced-route preflight"
        );
    }

    fn source_between<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
        source
            .split_once(start)
            .and_then(|(_, tail)| tail.split_once(end).map(|(body, _)| body))
            .unwrap_or_else(|| panic!("missing source boundary: {start} -> {end}"))
    }

    #[test]
    fn codepro_unified_executor_contract_routes_code_and_codepro_to_one_core() {
        let source = include_str!("agent.rs").replace("\r\n", "\n");
        let production_source = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("agent test module boundary");
        let code = source_between(
            production_source,
            "async fn reply_internal(",
            "async fn reply_internal_with_options(",
        );
        let codepro = source_between(
            production_source,
            "async fn reply_codepro_unified(",
            "async fn resolve_codepro_intent(",
        );

        for executor in [code, codepro] {
            let compact: String = executor.chars().filter(|c| !c.is_whitespace()).collect();
            assert!(compact.contains("self.reply_internal_with_options("));
        }
        assert!(!production_source.contains("async fn reply_codepro_conversation("));
        assert!(!production_source.contains("async fn reply_codepro_analysis("));
    }

    #[test]
    fn codepro_unified_executor_profiles_only_narrow_shared_capabilities() -> Result<()> {
        let conversation = UnifiedExecutorOptions::codepro_conversation();
        assert!(conversation.conversation_only);
        assert!(!conversation.read_only_analysis);
        assert!(conversation.simple_change.is_none());

        let analysis = UnifiedExecutorOptions::codepro_analysis();
        assert!(!analysis.conversation_only);
        assert!(analysis.read_only_analysis);
        assert!(analysis.simple_change.is_none());

        let project = tempfile::tempdir()?;
        let target = project.path().join("app.rs");
        std::fs::write(&target, "fn main() {}\n")?;
        let simple_change = UnifiedExecutorOptions::codepro_simple_change(SimpleChangeRequest {
            target: target.canonicalize()?,
        });
        assert!(!simple_change.conversation_only);
        assert!(!simple_change.read_only_analysis);
        assert_eq!(
            simple_change
                .simple_change
                .as_ref()
                .map(|request| request.target.as_path()),
            Some(target.canonicalize()?.as_path())
        );

        Ok(())
    }

