    #[test]
    fn sensitive_or_ambiguous_typed_repairs_pause_before_planner_or_worker() {
        let plan = codepro_role_plan(CodeProTaskKind::BugFix);
        let sensitive = codepro_initial_dag(
            "Change only .env with replace_exact; do not modify other files. Verify .env using host-selected typed verification. Required match_mode: exact_bytes; expected base64: Z2VuZXJpYyBwYXlsb2FkCg==; expected sha256: 02a56e1e0febfc4af3e2b5d95c4bd6f30b314e398b0da24567be5fd04b3e192b.",
            &plan,
        )
        .expect("a sensitive typed repair must fail closed before Planner");
        assert_eq!(sensitive.tasks.len(), 1);
        assert_eq!(sensitive.tasks[0].status, TaskStatus::Paused);
        assert!(sensitive.host_repair_actions_v1.is_empty());

        let credential = codepro_initial_dag(
            "Change only credentials/token with replace_exact; do not modify other files. Verify credentials/token using host-selected typed verification. Required match_mode: exact_bytes; expected base64: Z2VuZXJpYyBwYXlsb2FkCg==; expected sha256: 02a56e1e0febfc4af3e2b5d95c4bd6f30b314e398b0da24567be5fd04b3e192b.",
            &plan,
        )
        .expect("a credential typed repair must fail closed before Planner");
        assert_eq!(credential.tasks.len(), 1);
        assert_eq!(credential.tasks[0].status, TaskStatus::Paused);
        assert!(credential.host_repair_actions_v1.is_empty());

        let ambiguous = codepro_initial_dag(
            "Change only a.txt and modify only b.txt by appending LF; do not modify other files. Verify a.txt using host-selected typed verification. Required match_mode: exact_bytes; expected base64: Z2VuZXJpYyBwYXlsb2FkCg==; expected sha256: 02a56e1e0febfc4af3e2b5d95c4bd6f30b314e398b0da24567be5fd04b3e192b.",
            &plan,
        )
        .expect("ambiguous typed targets must fail closed before Planner");
        assert_eq!(ambiguous.tasks.len(), 1);
        assert_eq!(ambiguous.tasks[0].status, TaskStatus::Paused);
        assert!(ambiguous.host_repair_actions_v1.is_empty());

        let repeated_marker = codepro_initial_dag(
            "Change only a.txt and change only b.txt by appending LF; do not modify other files. Verify a.txt using host-selected typed verification. Required match_mode: exact_bytes; expected base64: Z2VuZXJpYyBwYXlsb2FkCg==; expected sha256: 02a56e1e0febfc4af3e2b5d95c4bd6f30b314e398b0da24567be5fd04b3e192b.",
            &plan,
        )
        .expect("repeated bounded markers must fail closed before Planner");
        assert_eq!(repeated_marker.tasks.len(), 1);
        assert_eq!(repeated_marker.tasks[0].status, TaskStatus::Paused);
        assert!(repeated_marker.host_repair_actions_v1.is_empty());

        let duplicate_values = codepro_initial_dag(
            "Change only a.txt by appending LF; do not modify other files. Verify a.txt using host-selected typed verification. Required match_mode: exact_bytes; expected base64: Z2VuZXJpYyBwYXlsb2FkCg==; expected sha256: 02a56e1e0febfc4af3e2b5d95c4bd6f30b314e398b0da24567be5fd04b3e192b; alternate base64: YWJj; alternate sha256: ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad.",
            &plan,
        )
        .expect("multiple matching typed values must fail closed before Planner");
        assert_eq!(duplicate_values.tasks.len(), 1);
        assert_eq!(duplicate_values.tasks[0].status, TaskStatus::Paused);
        assert!(duplicate_values.host_repair_actions_v1.is_empty());
    }

