    #[test]
    fn reviewer_policy_runs_only_for_required_eligible_tiers() {
        use crate::agents::agent_role::{
            codepro_role_plan_for_risk, CodeProRiskAssessment, CodeProRiskReason, CodeProRiskTier,
        };

        let plan = |tier, reason| {
            codepro_role_plan_for_risk(
                CodeProTaskKind::ComplexChange,
                &CodeProRiskAssessment {
                    tier,
                    reasons: vec![reason],
                },
            )
        };
        let l2 = plan(
            CodeProRiskTier::L2Feature,
            CodeProRiskReason::MultiFileOrUnknownWriteScope,
        );
        let l3 = plan(
            CodeProRiskTier::L3HighRiskRelease,
            CodeProRiskReason::PermissionBoundary,
        );

        assert!(!should_run_codepro_reviewer(&l2, false, false));
        assert!(should_run_codepro_reviewer(&l3, false, false));
        assert!(!should_run_codepro_reviewer(&l3, true, false));
        assert!(!should_run_codepro_reviewer(&l3, false, true));
    }

