    #[test]
    fn p2_production_undo_uses_transactional_checkpoint_and_needs_review_on_validation_failure() {
        let source = include_str!("agent.rs").replace("\r\n", "\n");
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .unwrap();
        let undo = source_between(
            production,
            "if is_codepro_undo_request(goal)",
            "let state_store = state_store",
        );
        assert!(undo.contains("latest_checkpoint_id"));
        assert!(undo.contains("restore_checkpoint_transaction"));
        assert!(undo.contains("CheckpointRestoreOutcome::NeedsReview"));
        assert!(undo.contains("CodeProPauseReason::RecoveryPaused"));

        let terminal_checkpoint = source_between(
            production,
            "let mut checkpoint_transaction_failed = false;",
            "let source_user_message_id = resume_request",
        );
        assert!(terminal_checkpoint.contains("commit_checkpoint_transaction"));
        assert!(terminal_checkpoint.contains("codepro_checkpoint_event_sequence"));
        assert!(terminal_checkpoint.contains("CodeProPauseReason::RecoveryPaused"));
        assert!(terminal_checkpoint.contains("NeedsReview"));
        assert!(terminal_checkpoint.contains("checkpoint_transaction_failed"));
        assert!(
            terminal_checkpoint
                .find("commit_checkpoint_transaction")
                .expect("transaction commit")
                < terminal_checkpoint
                    .find("let terminalization")
                    .expect("control-plane terminalization")
        );
    }

