    #[test]
    fn diagnostic_test_failure_requests_the_planned_downstream_coder() {
        let diagnostic = crate::agents::task_dag::TaskNode {
            id: "diagnostic".to_string(),
            name: "运行初始测试".to_string(),
            description: "运行 node tests.js".to_string(),
            role: AgentRole::Tester,
            depends_on: Vec::new(),
            acceptance_criteria: "记录真实失败".to_string(),
            status: crate::agents::task_dag::TaskStatus::Done,
            output: Some(crate::agents::task_dag::TaskOutput {
                patch: String::new(),
                change_report: "指定测试未通过".to_string(),
                test_results: Some("命令：node tests.js\n结果：测试失败\n退出码：1".to_string()),
                files_changed: Vec::new(),
                validation_not_run: None,
                usage: None,
            }),
            retry_count: 0,
        };
        let coder = crate::agents::task_dag::TaskNode {
            id: "code".to_string(),
            name: "修复实现".to_string(),
            description: "只修改实现代码".to_string(),
            role: AgentRole::Coder,
            depends_on: vec!["diagnostic".to_string()],
            acceptance_criteria: "测试恢复通过".to_string(),
            status: crate::agents::task_dag::TaskStatus::Skipped,
            output: None,
            retry_count: 0,
        };
        let mut dag = crate::agents::task_dag::TaskDAG::new(
            "修复 tests.js 暴露的问题",
            vec![diagnostic, coder],
        );
        let risk = crate::agents::agent_role::CodeProRiskAssessment {
            tier: crate::agents::agent_role::CodeProRiskTier::L2Feature,
            reasons: vec![
                crate::agents::agent_role::CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ],
        };

        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 0),
            (
                CodeProRecoveryDecision::RepairThenRetest,
                Some("diagnostic".to_string())
            )
        );
        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 1),
            (
                CodeProRecoveryDecision::RepairThenRetest,
                Some("diagnostic".to_string())
            )
        );
        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, MAX_TEST_REPAIR_ATTEMPTS),
            (
                CodeProRecoveryDecision::FinishFailed,
                Some("diagnostic".to_string())
            )
        );
        assert_ne!(
            dag.tasks
                .iter()
                .find(|task| task.id == "diagnostic")
                .unwrap()
                .status,
            crate::agents::task_dag::TaskStatus::RepairExhausted
        );
        dag.mark_test_repair_exhausted("diagnostic").unwrap();
        assert_eq!(
            dag.tasks
                .iter()
                .find(|task| task.id == "diagnostic")
                .unwrap()
                .status,
            crate::agents::task_dag::TaskStatus::RepairExhausted
        );
    }

    #[test]
    fn host_bounded_not_run_is_a_skipped_terminal_run_not_validation_failure() {
        let tester = crate::agents::task_dag::TaskNode {
            id: "static-analysis".to_string(),
            name: "独立验证用户目标".to_string(),
            description: "只读分析并给出建议".to_string(),
            role: AgentRole::Tester,
            depends_on: Vec::new(),
            acceptance_criteria: "保留静态分析".to_string(),
            status: crate::agents::task_dag::TaskStatus::Skipped,
            output: Some(crate::agents::task_dag::TaskOutput {
                patch: String::new(),
                change_report: "静态分析已保留；动态命令不在有界验证合同内。".to_string(),
                test_results: Some("命令：（未执行）\n退出码：NOT_RUN\nresult:NOT_RUN".to_string()),
                files_changed: Vec::new(),
                validation_not_run: None,
                usage: None,
            }),
            retry_count: 0,
        };
        let mut dag = crate::agents::task_dag::TaskDAG::new("分析项目", vec![tester]);
        let risk = crate::agents::agent_role::CodeProRiskAssessment {
            tier: crate::agents::agent_role::CodeProRiskTier::L2Feature,
            reasons: vec![
                crate::agents::agent_role::CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ],
        };

        assert!(codepro_skipped_dynamic_validation(&dag));
        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 0),
            (CodeProRecoveryDecision::Proceed, None)
        );

        let mut report =
            "# CodePro 执行结果\n\n动态验证未运行。\n\n<details>\n技术证据\n</details>".to_string();
        assert!(!insert_codepro_finalized_static_summary(&mut report, &dag));
        assert!(!report.contains("静态分析与优化建议"));

        dag.tasks[0]
            .output
            .as_mut()
            .unwrap()
            .test_results
            .as_mut()
            .unwrap()
            .push_str(&format!("\n{CODEPRO_FINALIZED_STATIC_SUMMARY_MARKER}"));
        assert!(insert_codepro_finalized_static_summary(&mut report, &dag));
        assert!(report.contains("### 静态分析记录"));
        assert!(report.contains("任务："));
        assert!(report.contains("角色："));
        assert!(report.contains("仅本子任务"));
        assert!(report.contains("静态分析已保留"));
        let (visible, technical) = report.split_once("<details>").unwrap();
        assert!(
            !visible.contains("静态分析已保留") && technical.contains("静态分析已保留"),
            "{report}"
        );
    }

    #[test]
    fn contract_reconciliation_replans_again_when_new_deterministic_evidence_arrives() {
        let coder = crate::agents::task_dag::TaskNode {
            id: "code".to_string(),
            name: "create the requested artifact".to_string(),
            description: "create hello.txt from the user goal".to_string(),
            role: AgentRole::Coder,
            depends_on: Vec::new(),
            acceptance_criteria: "match the authoritative user goal".to_string(),
            status: crate::agents::task_dag::TaskStatus::Done,
            output: Some(crate::agents::task_dag::TaskOutput {
                patch: "diff --git a/hello.txt b/hello.txt".to_string(),
                change_report: "tool evidence confirms the requested content is 16 bytes"
                    .to_string(),
                test_results: None,
                files_changed: vec!["hello.txt".to_string()],
                validation_not_run: None,
                usage: None,
            }),
            retry_count: 0,
        };
        let tester = crate::agents::task_dag::TaskNode {
            id: "test".to_string(),
            name: "verify the requested artifact".to_string(),
            description: "verify hello.txt without modifying it".to_string(),
            role: AgentRole::Tester,
            depends_on: vec!["code".to_string()],
            acceptance_criteria: "generated assertion expects 15 bytes".to_string(),
            status: crate::agents::task_dag::TaskStatus::Paused,
            output: Some(crate::agents::task_dag::TaskOutput {
                patch: String::new(),
                change_report: "repeated deterministic validation conflict".to_string(),
                test_results: Some(
                    "命令：{\"command\":\"verify hello.txt\"}\n结果：检查失败\n退出码：1\n输出：content_match=true actual_bytes=16 expected_bytes=15"
                        .to_string(),
                ),
                files_changed: Vec::new(),
                validation_not_run: None,
                usage: None,
            }),
            retry_count: 0,
        };
        let mut dag = crate::agents::task_dag::TaskDAG::new(
            "Create hello.txt with the exact requested text followed by a newline",
            vec![coder, tester],
        );
        dag.contracts.get_mut("test").unwrap().write_scope.clear();
        dag.record_contract_conflict(
            "test",
            "fingerprint-a",
            "content_match=true actual_bytes=16 expected_bytes=15",
        )
        .unwrap();
        let risk = crate::agents::agent_role::CodeProRiskAssessment {
            tier: crate::agents::agent_role::CodeProRiskTier::L2Feature,
            reasons: vec![
                crate::agents::agent_role::CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ],
        };

        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 0),
            (
                CodeProRecoveryDecision::RevisePlanWithinScope,
                Some("test".to_string())
            )
        );

        dag.reconcile_tester_contract("test").unwrap();
        let tester = dag.tasks.iter_mut().find(|task| task.id == "test").unwrap();
        tester.status = crate::agents::task_dag::TaskStatus::Done;
        tester.output.as_mut().unwrap().test_results = Some(
            "命令：{\"command\":\"verify hello.txt\"}\n结果：检查失败\n退出码：1\n输出：content_match=true actual_bytes=16 expected_bytes=15"
                .to_string(),
        );
        dag.record_contract_conflict(
            "test",
            "fingerprint-b",
            "content_match=true actual_bytes=16 expected_bytes=15 after revision",
        )
        .unwrap();
        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 1),
            (
                CodeProRecoveryDecision::RevisePlanWithinScope,
                Some("test".to_string())
            )
        );

        dag.reconcile_tester_contract("test").unwrap();
        dag.tasks
            .iter_mut()
            .find(|task| task.id == "test")
            .unwrap()
            .output
            .as_mut()
            .unwrap()
            .test_results = Some(
            "命令：{\"command\":\"verify hello.txt\"}\n结果：通过\n退出码：0\n输出：content_match=true actual_bytes=16"
                .to_string(),
        );
        assert_eq!(
            codepro_recovery_decision_for_run(&dag, &[], &risk, 1),
            (CodeProRecoveryDecision::Proceed, None)
        );
    }

    struct GlobalReplanPlannerProvider {
        calls: Arc<AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl crate::providers::base::Provider for GlobalReplanPlannerProvider {
        fn get_name(&self) -> &str {
            "p1-replan"
        }

        async fn fetch_supported_models(&self) -> Result<Vec<String>, ProviderError> {
            Ok(vec!["mock-model".to_string()])
        }

        async fn stream(
            &self,
            _model_config: &goose_providers::model::ModelConfig,
            system_prompt: &str,
            _messages: &[Message],
            tools: &[Tool],
        ) -> Result<MessageStream, ProviderError> {
            if system_prompt.contains("Generate a short title") {
                return Ok(stream_from_single_message(
                    Message::assistant().with_text("P1 global replan"),
                    ProviderUsage::new("mock-model".to_string(), Usage::default()),
                ));
            }
            assert!(
                system_prompt.contains("CodePro 的主 Agent 和需求分析专家"),
                "unexpected Planner system prompt: {system_prompt}"
            );
            assert!(
                tools.is_empty(),
                "Planner revisions must remain analysis-only"
            );
            let is_global_revision = _messages.iter().any(|message| {
                message.content.iter().any(|content| {
                    matches!(
                        content,
                        MessageContent::Text(text)
                            if text.text.contains("# 全局重规划")
                                && text.text.contains("supersedes_revision: 1")
                    )
                })
            });
            if is_global_revision {
                self.calls.fetch_add(1, Ordering::SeqCst);
            }
            let plan = serde_json::json!({
                "schema_version": 1,
                "goal": "analyze project tests",
                "tasks": [
                    {
                        "id": "diagnose-new-evidence",
                        "name": "diagnose the new verification evidence",
                        "description": "analyze the failed node test without editing project files",
                        "role": "tester",
                        "depends_on": [],
                        "acceptance_criteria": "the failed command and output are reproduced",
                        "budget": { "max_turns": 8 },
                        "scope": {
                            "read_scope": ["src/**", "tests/**"],
                            "write_scope": [],
                            "behavior_scope": ["reproduce the current failure"],
                            "forbidden_scope": [".git/**", ".env", "credentials/**"],
                            "required_evidence": ["worker_report", "command", "exit_code", "test_result"]
                        }
                    }
                ]
            });
            Ok(stream_from_single_message(
                Message::assistant().with_text(plan.to_string()),
                ProviderUsage::new("mock-model".to_string(), Usage::default()),
            ))
        }
    }

