    #[test]
    fn persisted_and_requested_risk_reconcile_monotonically_before_execution() {
        use crate::agents::agent_role::{CodeProRiskReason, CodeProRiskTier};

        let assessment = |tier, reason| CodeProRiskAssessment {
            tier,
            reasons: vec![reason],
        };
        let (preserved, preserved_plan, preserved_previous) = reconcile_codepro_execution_risk(
            CodeProTaskKind::ComplexChange,
            Some(assessment(
                CodeProRiskTier::L3HighRiskRelease,
                CodeProRiskReason::RemoteSideEffect,
            )),
            assessment(
                CodeProRiskTier::L1ReversibleChange,
                CodeProRiskReason::SingleWorkspaceFile,
            ),
            true,
        );
        assert_eq!(preserved.tier, CodeProRiskTier::L3HighRiskRelease);
        assert!(preserved_plan.review_required);
        assert_eq!(preserved_previous, None);

        let (upgraded, upgraded_plan, upgraded_previous) = reconcile_codepro_execution_risk(
            CodeProTaskKind::ComplexChange,
            Some(assessment(
                CodeProRiskTier::L2Feature,
                CodeProRiskReason::MultiFileOrUnknownWriteScope,
            )),
            assessment(
                CodeProRiskTier::L3HighRiskRelease,
                CodeProRiskReason::PermissionBoundary,
            ),
            true,
        );
        assert_eq!(upgraded.tier, CodeProRiskTier::L3HighRiskRelease);
        assert!(upgraded_plan.review_required);
        assert_eq!(upgraded_previous, Some(CodeProRiskTier::L2Feature));

        let (initial, initial_plan, initial_previous) = reconcile_codepro_execution_risk(
            CodeProTaskKind::ComplexChange,
            None,
            assessment(
                CodeProRiskTier::L2Feature,
                CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ),
            false,
        );
        assert_eq!(initial.tier, CodeProRiskTier::L2Feature);
        assert!(!initial_plan.review_required);
        assert_eq!(initial_previous, None);

        let (legacy, legacy_plan, legacy_previous) = reconcile_codepro_execution_risk(
            CodeProTaskKind::ComplexChange,
            None,
            assessment(
                CodeProRiskTier::L2Feature,
                CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ),
            true,
        );
        assert_eq!(legacy.tier, CodeProRiskTier::L3HighRiskRelease);
        assert!(legacy_plan.review_required);
        assert_eq!(legacy_previous, None);
    }

    #[test]
    fn codepro_intent_failure_preserves_the_task_without_changing_business_route() {
        for (warning, expected_reason) in [
            (
                CodeProIntentWarning::SemanticRouterUnavailable,
                "意图识别服务暂时不可用",
            ),
            (
                CodeProIntentWarning::SemanticRouterInvalidOutput,
                "意图识别结果无效",
            ),
        ] {
            let notification =
                codepro_intent_warning_notification(warning, CodeProIntent::ReadOnly);
            let system_notification = notification
                .content
                .iter()
                .find_map(MessageContent::as_system_notification)
                .expect("intent degradation must be a visible system notification");
            assert_eq!(
                system_notification.notification_type,
                SystemNotificationType::InlineMessage
            );
            assert!(system_notification.msg.contains(expected_reason));
            assert!(system_notification.msg.contains("原任务和授权边界已保留"));
            assert!(system_notification.msg.contains("未进入其他执行路径"));

            let tool_action =
                codepro_intent_warning_notification(warning, CodeProIntent::ToolAction);
            let tool_action_notification = tool_action
                .content
                .iter()
                .find_map(MessageContent::as_system_notification)
                .unwrap();
            assert_eq!(tool_action_notification.msg, system_notification.msg);
        }

        let source = include_str!("agent.rs").replace("\r\n", "\n");
        let production_source = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("agent test module boundary");
        let resolver = source_between(
            production_source,
            "async fn resolve_codepro_intent(",
            "async fn multi_agent_reply(",
        );
        assert!(!resolver.contains("resolve_fallback(AgentRole::Planner)"));
        assert!(resolver.contains("CodeProIntent::ReadOnly"));
        assert!(resolver.contains("CodeProSemanticDecision"));
        assert!(!resolver.contains("trying fallback"));

        assert!(!production_source.contains(
            "let constraint = detect_codepro_constraint_in_workspace(&goal, &session.working_dir);"
        ));
        let routing = source_between(
            production_source,
            "let intent_run_id = active_run_id",
            "#[allow(clippy::too_many_arguments)]\n    async fn reply_codepro_with_intent(",
        );
        let progress = routing
            .find("codepro_intent_progress_message(&goal)")
            .expect("visible intent progress");
        let resolution = routing
            .find(".resolve_codepro_intent(")
            .expect("semantic intent resolution");
        let visible_warning = routing
            .find("codepro_intent_warning_notification(")
            .expect("visible semantic failure warning");
        let preserved_failure = routing
            .find("the original task was preserved for retry")
            .expect("semantic failure preserves the task");
        let delegated_route = routing
            .find(".reply_codepro_with_intent(")
            .expect("intent-specific execution route");
        assert!(progress < resolution);
        assert!(resolution < visible_warning);
        assert!(visible_warning < preserved_failure);
        assert!(preserved_failure < delegated_route);
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct ParityObservation {
        tool_name: String,
        arguments: Value,
        failed: bool,
        text: String,
    }

    struct ReadOnlyParityProvider {
        path: String,
        call_count: AtomicUsize,
    }

    #[async_trait::async_trait]
    impl crate::providers::base::Provider for ReadOnlyParityProvider {
        async fn stream(
            &self,
            _model_config: &goose_providers::model::ModelConfig,
            _system_prompt: &str,
            _messages: &[Message],
            _tools: &[Tool],
        ) -> Result<MessageStream, ProviderError> {
            let call_index = self.call_count.fetch_add(1, Ordering::SeqCst);
            let usage = ProviderUsage::new("mock-model".to_string(), Usage::default());
            let message = if call_index == 0 {
                Message::assistant().with_tool_request(
                    "parity-tree",
                    Ok(CallToolRequestParams::new("tree").with_arguments(
                        json!({"path": self.path, "depth": 1})
                            .as_object()
                            .expect("tree arguments")
                            .clone(),
                    )),
                )
            } else {
                Message::assistant().with_text("parity complete")
            };
            Ok(stream_from_single_message(message, usage))
        }

        fn get_name(&self) -> &str {
            "read-only-parity"
        }
    }

    async fn run_read_only_parity_case(
        project: &Path,
        codepro: bool,
        requested_path: &str,
    ) -> Result<ParityObservation> {
        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let config = AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        );
        let agent = Agent::with_config(config);
        let session = session_manager
            .create_session(
                project.to_path_buf(),
                if codepro {
                    "CodePro parity".to_string()
                } else {
                    "Code parity".to_string()
                },
                if codepro {
                    SessionType::CodePro
                } else {
                    SessionType::User
                },
                GooseMode::Auto,
            )
            .await?;
        let developer = get_enabled_extensions()
            .into_iter()
            .find(|extension| extension.name() == "developer")
            .expect("developer extension should be enabled");
        agent.add_extension(developer, &session.id).await?;
        agent
            .update_provider(
                Arc::new(ReadOnlyParityProvider {
                    path: requested_path.to_string(),
                    call_count: AtomicUsize::new(0),
                }),
                goose_providers::model::ModelConfig::new("mock-model"),
                &session.id,
            )
            .await?;
        let session_config = SessionConfig {
            id: session.id.clone(),
            schedule_id: None,
            max_turns: Some(8),
            retry_config: None,
        };
        let reply_stream = if codepro {
            agent
                .reply_codepro_with_intent_for_test(
                    session,
                    Message::user().with_text("只读检查目标路径"),
                    session_config,
                    None,
                    CodeProIntentDecision {
                        intent: CodeProIntent::ReadOnly,
                        clarification: None,
                        public_summary: None,
                        warning: None,
                    },
                    CodeProRunContext::default(),
                )
                .await?
        } else {
            agent
                .reply(
                    Message::user().with_text("只读检查目标路径"),
                    session_config,
                    None,
                )
                .await?
        };
        tokio::pin!(reply_stream);
        let mut tool_name = None;
        let mut arguments = None;
        let mut failed = None;
        let mut text = None;
        while let Some(event) = reply_stream.next().await {
            let AgentEvent::Message(message) = event? else {
                continue;
            };
            for content in message.content {
                match content {
                    MessageContent::ToolRequest(request) if request.id == "parity-tree" => {
                        let call = request
                            .tool_call
                            .map_err(|error| anyhow!(error.to_string()))?;
                        tool_name = Some(codepro_unqualified_tool_name(&call.name).to_string());
                        arguments = Some(Value::Object(call.arguments.unwrap_or_default()));
                    }
                    MessageContent::ToolResponse(response) if response.id == "parity-tree" => {
                        failed = Some(codepro_tool_result_failed(&response.tool_result));
                        text = Some(summarize_codepro_tool_result(&response.tool_result).1);
                    }
                    _ => {}
                }
            }
        }

        Ok(ParityObservation {
            tool_name: tool_name.ok_or_else(|| anyhow!("missing parity tool request"))?,
            arguments: arguments.ok_or_else(|| anyhow!("missing parity tool arguments"))?,
            failed: failed.ok_or_else(|| anyhow!("missing parity tool result status"))?,
            text: text.ok_or_else(|| anyhow!("missing parity tool result text"))?,
        })
    }

    #[tokio::test]
    async fn codepro_code_action_parity_keeps_successful_read_result_equivalent() -> Result<()> {
        let project = tempfile::tempdir()?;
        let target = project.path().join("src/lib.rs");
        std::fs::create_dir_all(target.parent().expect("target parent"))?;
        std::fs::write(&target, "pub const VALUE: &str = \"u30\";\n")?;
        let before = std::fs::read(&target)?;

        let code = run_read_only_parity_case(project.path(), false, "src").await?;
        let codepro = run_read_only_parity_case(project.path(), true, "src").await?;

        assert_eq!(code, codepro);
        assert!(!code.failed);
        assert_eq!(std::fs::read(&target)?, before);
        Ok(())
    }

    #[tokio::test]
    async fn codepro_code_action_parity_keeps_missing_path_failure_equivalent() -> Result<()> {
        let project = tempfile::tempdir()?;
        let code =
            run_read_only_parity_case(project.path(), false, "missing-u30-directory").await?;
        let codepro =
            run_read_only_parity_case(project.path(), true, "missing-u30-directory").await?;

        assert_eq!(code.tool_name, "tree");
        assert_eq!(codepro.tool_name, "tree");
        assert_eq!(code.arguments, codepro.arguments);
        assert!(code.failed);
        assert!(codepro.failed);
        assert_eq!(code.text, codepro.text);
        Ok(())
    }

