    #[tokio::test]
    async fn codepro_write_hook_attributes_only_registered_workspace_changes() -> Result<()> {
        let project = tempfile::tempdir()?;
        let data = tempfile::tempdir()?;
        tokio::fs::write(project.path().join("tracked.txt"), "before\n").await?;
        tokio::fs::write(project.path().join("unrelated.txt"), "before\n").await?;
        let evidence = Arc::new(CodeProEvidence::capture(project.path()).await?);
        let session_manager = Arc::new(SessionManager::new(data.path().to_path_buf()));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let config = AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        )
        .with_codepro_evidence(evidence.clone());
        let agent = Agent::with_config(config);
        let session = session_manager
            .create_session(
                project.path().to_path_buf(),
                "evidence test".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await?;
        let input = json!({"path": "tracked.txt", "content": "after\n"});

        agent
            .emit_pre_tool_extended_hooks("developer__write", Some(&input), &session)
            .await;
        tokio::fs::write(project.path().join("tracked.txt"), "after\n").await?;
        tokio::fs::write(project.path().join("unrelated.txt"), "external\n").await?;
        let result = evidence.collect().await?;

        assert_eq!(result.files_changed, vec!["tracked.txt"]);
        assert!(result.patch.contains("-before"));
        assert!(result.patch.contains("+after"));
        assert!(!result.patch.contains("unrelated.txt"));
        assert!(!result.patch.contains("external"));
        Ok(())
    }

