    #[test]
    fn codepro_read_only_shell_guard_allows_inspection_commands() {
        for command in [
            "dir",
            "Get-ChildItem -Recurse",
            "Get-Content Cargo.toml -Raw",
            "Select-String -Path src/*.rs -Pattern TODO",
            "rg -n TODO .",
            "git status --short",
            "git diff -- crates/goose/src/agents/agent.rs",
            "git log -5 --oneline",
            "ls -la",
            "cat Cargo.toml",
        ] {
            assert!(
                is_codepro_read_only_shell_command(command),
                "expected read-only command: {command}"
            );
        }
    }

    #[test]
    fn codepro_read_only_shell_guard_rejects_mutation_and_shell_composition() {
        for command in [
            "Set-Content Cargo.toml broken",
            "echo broken > Cargo.toml",
            "dir; Remove-Item Cargo.toml",
            "dir && del Cargo.toml",
            "Get-Content Cargo.toml | Set-Content copy.txt",
            "rg --pre powershell TODO .",
            "rg --pre=powershell TODO .",
            "git diff --output=copy.patch",
            "git checkout -- Cargo.toml",
            "git reset --hard",
            "python -c \"open('Cargo.toml','w').write('broken')\"",
            "cmd /c dir",
        ] {
            assert!(
                !is_codepro_read_only_shell_command(command),
                "expected rejected command: {command}"
            );
        }
    }

