        let started = tracker.activities(&request);
        let started_event = started[0]
            .event
            .as_ref()
            .expect("read request should carry structured activity data");
        assert_eq!(started_event.event_id, "tool-structured");
        assert_eq!(started_event.event_type, ActivityEventKind::FileRead);
