    #[test]
    fn codepro_report_keeps_plain_summary_before_folded_technical_details() {
        let cases = [
            (
                CodeProWorkflow::Test,
                "# CodePro 测试报告\n\n## 结论\n\n完成。\n\n## 确认发现的问题\n\n无。\n\n## 已通过检查\n\n通过。\n\n## 未完成和未验证\n\n无。\n\n## 用户下一步\n\n无。\n\n<details>\n技术证据\n</details>\n",
                "结论",
                "未完成和未验证",
                "结论",
            ),
            (
                CodeProWorkflow::Change,
                "# CodePro 修复报告\n\n## 是否修好\n\n已修好。\n\n## 修改了哪些文件\n\n- app.rs\n\n## 用户会看到什么变化\n\n已更新。\n\n## 运行了哪些测试\n\n通过。\n\n## 仍有限制\n\n无。\n\n<details>\n技术证据\n</details>\n",
                "是否修好",
                "仍有限制",
                "用户会看到什么变化",
            ),
        ];

        for (workflow, template, approved_heading, limitation_heading, workspace_heading) in cases {
            let mut report = template.to_string();
            insert_codepro_report_note(
                &mut report,
                workflow,
                CodeProReportNoteKind::ReviewApproved,
                "✅ 独立审查通过",
            );
            insert_codepro_report_note(
                &mut report,
                workflow,
                CodeProReportNoteKind::Limitation,
                "❌ 独立审查未通过",
            );
            insert_codepro_report_note(
                &mut report,
                workflow,
                CodeProReportNoteKind::Limitation,
                "⏸️ 当前任务已保存检查点",
            );
            insert_codepro_report_note(
                &mut report,
                workflow,
                CodeProReportNoteKind::Workspace,
                "📂 当前项目说明",
            );
            insert_codepro_report_technical_detail(&mut report, "\n项目路径：`D:\\CodeBuddy`\n");

            for (heading, note) in [
                (approved_heading, "独立审查通过"),
                (limitation_heading, "独立审查未通过"),
                (limitation_heading, "当前任务已保存检查点"),
                (workspace_heading, "当前项目说明"),
            ] {
                let start = report.find(&format!("## {heading}")).unwrap();
                let note = report.find(note).unwrap();
                let end = report
                    .get(start + 3..)
                    .expect("heading position comes from a UTF-8 marker")
                    .find("\n## ")
                    .map(|offset| start + 3 + offset)
                    .unwrap_or_else(|| report.find("\n<details>").unwrap());
                assert!(start < note && note < end, "{heading}: {report}");
            }
            let details_position = report.find("<details>").expect("details");
            let path_position = report.find("D:\\CodeBuddy").expect("path");
            let details_end = report.find("</details>").expect("details end");
            assert!(path_position > details_position);
            assert!(path_position < details_end);

            let mut no_review = template.to_string();
            insert_codepro_report_note(
                &mut no_review,
                workflow,
                CodeProReportNoteKind::Workspace,
                "当前项目说明",
            );
            assert!(!no_review.contains("独立审查"));
        }
    }

