    fn rejected_change_review() -> crate::agents::reviewer_agent::ReviewVerdict {
        crate::agents::reviewer_agent::ReviewVerdict {
            approved: false,
            summary: "需要返工".to_string(),
            issues: vec!["失败分支没有恢复会话".to_string()],
            remediation_tasks: vec![crate::agents::reviewer_agent::ReviewRemediation {
                problem: "失败分支没有恢复会话".to_string(),
                files: vec!["src/auth/session.rs".to_string()],
                acceptance_criteria: "失败分支回归测试通过".to_string(),
            }],
        }
    }

    #[test]
    fn reviewer_policy_allows_exactly_two_change_remediation_rounds() {
        let rejected = rejected_change_review();

        assert!(should_schedule_review_remediation(
            CodeProWorkflow::Change,
            0,
            &rejected
        ));
        assert!(should_schedule_review_remediation(
            CodeProWorkflow::Change,
            1,
            &rejected
        ));
        assert!(!should_schedule_review_remediation(
            CodeProWorkflow::Change,
            2,
            &rejected
        ));
        assert_eq!(MAX_REVIEW_REPAIR_ROUNDS, 2);
    }

    #[test]
    fn reviewer_policy_never_creates_coder_for_test_approval_or_empty_remediation() {
        let rejected = rejected_change_review();
        assert!(!should_schedule_review_remediation(
            CodeProWorkflow::Test,
            0,
            &rejected
        ));

        let mut approved = rejected.clone();
        approved.approved = true;
        approved.issues.clear();
        approved.remediation_tasks.clear();
        assert!(!should_schedule_review_remediation(
            CodeProWorkflow::Change,
            0,
            &approved
        ));

        let mut empty = rejected;
        empty.remediation_tasks.clear();
        assert!(!should_schedule_review_remediation(
            CodeProWorkflow::Change,
            0,
            &empty
        ));
    }

