    #[test]
    fn http_attempt_exhaustion_is_needs_review_and_manual_review_only() {
        let error = anyhow::Error::new(
            goose_providers::errors::ProviderError::ExternalHttpAttemptBudgetExceeded {
                authorization_id: "authorization-test".to_string(),
                used: 2,
                cap: 2,
            },
        );
        let mut report = String::new();
        assert!(insert_reviewer_execution_failure(
            &mut report,
            CodeProWorkflow::Change,
            &error,
        ));
        assert!(report.contains("NEEDS_REVIEW"));
        assert!(report.contains("retry is unavailable"));

        let mut dag = crate::agents::task_dag::TaskDAG::new("goal", vec![]);
        dag.mark_external_http_attempt_budget_exhausted();
        assert_eq!(
            codepro_report_recovery_action(CodeProTerminalOutcome::Paused, &dag),
            ReportRecoveryAction::ManualReview
        );
    }

    #[test]
    fn reviewer_failure_summary_preserves_completed_task_evidence() {
        let mut report =
            "任务 code：已完成\n文件：src/auth.rs\n命令：cargo test\n退出码：0\n".to_string();

        let action_limited = insert_reviewer_execution_failure(
            &mut report,
            CodeProWorkflow::Change,
            &anyhow!("Reviewer 主模型失败；备用模型也失败"),
        );

        assert!(!action_limited);
        for evidence in [
            "任务 code：已完成",
            "src/auth.rs",
            "cargo test",
            "退出码：0",
        ] {
            assert!(report.contains(evidence));
        }
        assert!(report.contains("独立审查执行失败"));
        assert!(report.contains("备用模型也失败"));
    }

    #[test]
