    struct StopHookTestEnv {
        temp_dir: TempDir,
        hook_log: PathBuf,
        payload_path: PathBuf,
    }

    fn hook_invocation_count(hook_log: &PathBuf) -> Result<usize> {
        let contents = std::fs::read_to_string(hook_log)
            .with_context(|| format!("reading hook log {}", hook_log.display()))?;
        Ok(contents.lines().count())
    }

    impl StopHookTestEnv {
        fn new(script: &str) -> Result<Self> {
            let temp_dir = tempfile::tempdir()?;
            let plugin_dir = temp_dir.path().join("stop-blocker");
            std::fs::create_dir_all(plugin_dir.join("hooks"))?;
            let script_name = if cfg!(windows) {
                "block.cmd"
            } else {
                "block.sh"
            };
            let command = if cfg!(windows) {
                format!(r#""${{PLUGIN_ROOT}}/{script_name}""#)
            } else {
                // The fixture writes a regular file, not an executable plugin entry.
                format!(r#"sh "${{PLUGIN_ROOT}}/{script_name}""#)
            };
            let hooks = serde_json::json!({
                "hooks": {
                    "Stop": [{
                        "hooks": [{"type": "command", "command": command}]
                    }]
                }
            });
            std::fs::write(
                plugin_dir.join("hooks/hooks.json"),
                serde_json::to_vec_pretty(&hooks)?,
            )?;
            std::fs::write(plugin_dir.join(script_name), script)?;

            Ok(Self {
                temp_dir,
                hook_log: plugin_dir.join("hook.log"),
                payload_path: plugin_dir.join("payload.json"),
            })
        }

        fn hook_manager(&self) -> crate::hooks::HookManager {
            crate::hooks::HookManager::from_plugins_for_test(vec![DiscoveredPlugin {
                name: "stop-blocker".into(),
                root: self.temp_dir.path().join("stop-blocker"),
                scope: PluginScope::Project,
            }])
        }

        fn data_dir(&self) -> PathBuf {
            self.temp_dir.path().join("data")
        }

        fn hook_invocations(&self) -> Result<usize> {
            hook_invocation_count(&self.hook_log)
        }

        fn stop_payload(&self) -> Result<Value> {
            let payload = std::fs::read_to_string(&self.payload_path)?;
            Ok(serde_json::from_str(&payload)?)
        }
    }

