    #[derive(Default)]
    struct BoundedTesterNotRunProvider {
        call_count: AtomicUsize,
        tool_names: std::sync::Mutex<Vec<Vec<String>>>,
        system_prompts: std::sync::Mutex<Vec<String>>,
        model_configs: std::sync::Mutex<Vec<goose_providers::model::ModelConfig>>,
    }

    #[async_trait::async_trait]
    impl crate::providers::base::Provider for BoundedTesterNotRunProvider {
        async fn stream(
            &self,
            model_config: &goose_providers::model::ModelConfig,
            system_prompt: &str,
            _messages: &[Message],
            tools: &[Tool],
        ) -> Result<MessageStream, ProviderError> {
            let call = self.call_count.fetch_add(1, Ordering::SeqCst);
            self.tool_names
                .lock()
                .unwrap()
                .push(tools.iter().map(|tool| tool.name.to_string()).collect());
            self.system_prompts
                .lock()
                .unwrap()
                .push(system_prompt.to_string());
            self.model_configs
                .lock()
                .unwrap()
                .push(model_config.clone());
            let message = match call {
                0 => Message::assistant().with_tool_request(
                    "bounded-test-not-run",
                    Ok(CallToolRequestParams::new("shell").with_arguments(
                        json!({"command": "netstat -ano | findstr :5000"})
                            .as_object()
                            .unwrap()
                            .clone(),
                    )),
                ),
                _ => Message::assistant().with_text(format!(
                    "{CODEPRO_FINAL_STATIC_START}静态分析与优化建议：为成绩字段增加服务端范围校验，并补充边界值回归测试。动态验证：NOT_RUN。{CODEPRO_FINAL_STATIC_END}"
                )),
            };
            Ok(stream_from_single_message(
                message,
                ProviderUsage::new("mock-model".to_string(), Usage::default()),
            ))
        }

        fn get_name(&self) -> &str {
            "bounded-tester-not-run-provider"
        }
    }

    #[tokio::test]
    async fn p0_bounded_tester_rejects_compound_command_with_recoverable_receipt() -> Result<()> {
        let project = tempfile::tempdir()?;
        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let mut session = session_manager
            .create_session(
                project.path().to_path_buf(),
                "bounded tester NOT_RUN finalization".to_string(),
                SessionType::CodePro,
                GooseMode::Auto,
            )
            .await?;
        bind_test_workspace(&session_manager, &mut session).await?;
        let permission_scope = CodeProTaskScope::new_bound(
            "bounded-run",
            "bounded-tester",
            project.path(),
            vec!["./**".to_string()],
            Vec::new(),
        )
        .and_then(|scope| scope.with_permission_session_id(&session.id))
        .map_err(anyhow::Error::msg)?;
        let config = AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        )
        .with_codepro_permission_scope(permission_scope)
        .with_codepro_agent_role(AgentRole::Tester);
        let agent = Agent::with_config(config);
        let developer = get_enabled_extensions()
            .into_iter()
            .find(|extension| extension.name() == "developer")
            .expect("developer extension should be enabled");
        agent.add_extension(developer, &session.id).await?;
        let provider = Arc::new(BoundedTesterNotRunProvider::default());
        agent
            .update_provider(
                provider.clone(),
                goose_providers::model::ModelConfig::new("mock-model"),
                &session.id,
            )
            .await?;

        let conversation = Conversation::new_unvalidated([Message::user()
            .with_text("analyze the project, run bounded validation, and give suggestions")]);
        let session_config = SessionConfig {
            id: session.id.clone(),
            schedule_id: None,
            max_turns: Some(4),
            retry_config: None,
        };
        let mut reply = agent
            .reply_internal(
                conversation,
                session_config,
                session,
                None,
                provider.clone(),
            )
            .await?;
        let mut visible_text = Vec::new();
        let mut rejection = None;
        while let Some(event) = reply.next().await {
            if let AgentEvent::Message(message) = event? {
                for content in &message.content {
                    if let MessageContent::ToolResponse(response) = content {
                        if response.id == "bounded-test-not-run" {
                            let result = response.tool_result.as_ref().expect("rejection receipt");
                            assert_eq!(result.is_error, Some(true));
                            rejection = result.structured_content.clone();
                        }
                    }
                }
                let text = agent_visible_message_text(&message);
                if !text.is_empty() {
                    visible_text.push(text);
                }
            }
        }

        assert_eq!(provider.call_count.load(Ordering::SeqCst), 2);
        let presented_tools = provider.tool_names.lock().unwrap();
        assert!(!presented_tools[0].is_empty());
        let rejection = rejection.expect("bounded shell must return its structured rejection");
        assert_eq!(rejection["error_code"], "compound_command_not_supported");
        assert_eq!(rejection["recoverable"], true);
        assert!(visible_text.iter().any(|text| text.contains("成绩字段")));
        assert!(visible_text.iter().any(|text| text.contains("NOT_RUN")));
        Ok(())
    }

