    #[tokio::test]
    async fn codepro_failed_validation_retry_bypasses_provider_and_reruns_only_test() -> Result<()>
    {
        let project = tempfile::tempdir()?;
        tokio::fs::write(project.path().join("app.rs"), "old\n").await?;
        tokio::fs::create_dir_all(project.path().join("validation_fixture/src")).await?;
        tokio::fs::write(
            project.path().join("validation_fixture/Cargo.toml"),
            "[package]\nname = \"validation-fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .await?;
        tokio::fs::write(
            project.path().join("validation_fixture/Cargo.lock"),
            "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = \"validation-fixture\"\nversion = \"0.1.0\"\n",
        )
        .await?;
        tokio::fs::write(
            project.path().join("validation_fixture/src/lib.rs"),
            "pub fn broken( {\n",
        )
        .await?;
        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let config = with_test_http_attempt_gate(AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        ));
        let agent = Agent::with_config(config);
        let mut session = session_manager
            .create_session(
                project.path().to_path_buf(),
                "CodePro failed validation retry".to_string(),
                SessionType::CodePro,
                GooseMode::Auto,
            )
            .await?;
        bind_test_workspace(&session_manager, &mut session).await?;
        let developer = get_enabled_extensions()
            .into_iter()
            .find(|extension| extension.name() == "developer")
            .expect("developer extension should be enabled");
        agent.add_extension(developer, &session.id).await?;
        let provider = Arc::new(CodeProSimpleTerminalProvider {
            call_count: AtomicUsize::new(0),
            scenario: SimpleTerminalScenario::RetryFixture,
            project: project.path().to_path_buf(),
        });
        agent
            .update_provider(
                provider.clone(),
                goose_providers::model::ModelConfig::new("mock-model"),
                &session.id,
            )
            .await?;
        let session_config = SessionConfig {
            id: session.id.clone(),
            schedule_id: None,
            max_turns: Some(8),
            retry_config: None,
        };

        let source_user_message = Message::user()
            .with_id("source-user-1")
            .with_text("修改 `app.rs` 中的标题并运行最小相关测试");
        session_manager
            .add_message(&session.id, &source_user_message)
            .await?;
        let session_with_source = session_manager.get_session(&session.id, true).await?;
        let initial_options = UnifiedExecutorOptions::codepro_simple_change(
            crate::agents::codepro_simple_change::SimpleChangeRequest {
                target: project.path().join("app.rs").canonicalize()?,
            },
        )
        .with_simple_change_terminal_context(SimpleChangeTerminalContext {
            run_id: "source-run-1".to_string(),
            source_user_message_id: "source-user-1".to_string(),
            retry_of_terminal_message_id: None,
            tool_action_count: 0,
        });
        let initial_stream = agent
            .reply_codepro_unified(
                &session_with_source,
                source_user_message,
                session_config.clone(),
                None,
                initial_options,
            )
            .await?;
        tokio::pin!(initial_stream);
        while let Some(event) = initial_stream.next().await {
            event?;
        }
        assert_eq!(provider.call_count.load(Ordering::SeqCst), 3);

        let reloaded = session_manager.get_session(&session.id, true).await?;
        let source_terminals = reloaded
            .conversation
            .as_ref()
            .expect("conversation should persist")
            .messages()
            .iter()
            .flat_map(|message| message.content.iter())
            .filter_map(MessageContent::as_system_notification)
            .filter(|notification| {
                notification.notification_type == SystemNotificationType::TurnTerminal
            })
            .filter_map(|notification| notification.data.as_ref())
            .collect::<Vec<_>>();
        let source_terminal_id = source_terminals
            .iter()
            .copied()
            .find(|data| data["status"] == "failed")
            .and_then(|data| data["terminal_message_id"].as_str())
            .unwrap_or_else(|| panic!("initial failed terminal: {source_terminals:?}"))
            .to_string();
        resolve_validation_retry_source(
            reloaded
                .conversation
                .as_ref()
                .expect("conversation should persist")
                .messages(),
            &session.id,
            &ValidationRetryLink {
                source_run_id: "source-run-1".to_string(),
                source_user_message_id: "source-user-1".to_string(),
                source_terminal_message_id: source_terminal_id.clone(),
            },
        )
        .unwrap_or_else(|error| {
            let texts = reloaded
                .conversation
                .as_ref()
                .expect("conversation should persist")
                .messages()
                .iter()
                .map(agent_visible_message_text)
                .filter(|text| !text.is_empty())
                .collect::<Vec<_>>();
            panic!(
                "retry fixture source must be valid: {error}; terminals={source_terminals:?}; texts={texts:?}"
            )
        });

        let retry_stream = agent
            .reply_codepro_with_resume(
                Message::user()
                    .with_id("retry-user-1")
                    .with_text("重新运行失败的验证"),
                session_config,
                None,
                Some("retry-run-1".to_string()),
                Some(CodeProResumeRequest {
                    normalized_user_input: None,
                    strategy: CodeProRetryStrategy::RetryFailedValidation,
                    checkpoint_id: None,
                    source_run_id: "source-run-1".to_string(),
                    source_user_message_id: "source-user-1".to_string(),
                    source_terminal_message_id: Some(source_terminal_id.clone()),
                    approval: None,
                }),
            )
            .await?;
        tokio::pin!(retry_stream);
        let mut retry_messages = Vec::new();
        while let Some(event) = retry_stream.next().await {
            if let AgentEvent::Message(message) = event? {
                retry_messages.push(message);
            }
        }

        assert_eq!(provider.call_count.load(Ordering::SeqCst), 3);
        let retry_tool_names = retry_messages
            .iter()
            .flat_map(|message| message.content.iter())
            .filter_map(|content| match content {
                MessageContent::ToolRequest(request) => request
                    .tool_call
                    .as_ref()
                    .ok()
                    .map(|call| call.name.as_ref()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(retry_tool_names.len(), 1);
        assert!(retry_tool_names[0] == "shell" || retry_tool_names[0].ends_with("__shell"));
        assert!(!retry_tool_names.iter().any(|name| name == &"write"
            || name.ends_with("__write")
            || name == &"edit"
            || name.ends_with("__edit")));
        let retry_terminal = retry_messages
            .iter()
            .flat_map(|message| message.content.iter())
            .filter_map(MessageContent::as_system_notification)
            .find(|notification| {
                notification.notification_type == SystemNotificationType::TurnTerminal
            })
            .and_then(|notification| notification.data.as_ref())
            .expect("retry terminal");
        assert_eq!(
            retry_terminal["retry_of_terminal_message_id"],
            source_terminal_id
        );
        assert_eq!(retry_terminal["status"], "failed");
        let failed_retry_terminal_id = retry_terminal["terminal_message_id"]
            .as_str()
            .expect("failed retry terminal id")
            .to_string();

        tokio::fs::write(
            project.path().join("validation_fixture/src/lib.rs"),
            "pub fn fixed() {}\n",
        )
        .await?;
        let pass_stream = agent
            .reply_codepro_with_resume(
                Message::user()
                    .with_id("retry-user-2")
                    .with_text("重新运行失败的验证"),
                SessionConfig {
                    id: session.id.clone(),
                    schedule_id: None,
                    max_turns: Some(8),
                    retry_config: None,
                },
                None,
                Some("retry-run-2".to_string()),
                Some(CodeProResumeRequest {
                    normalized_user_input: None,
                    strategy: CodeProRetryStrategy::RetryFailedValidation,
                    checkpoint_id: None,
                    source_run_id: "retry-run-1".to_string(),
                    source_user_message_id: "retry-user-1".to_string(),
                    source_terminal_message_id: Some(failed_retry_terminal_id.clone()),
                    approval: None,
                }),
            )
            .await?;
        tokio::pin!(pass_stream);
        let mut pass_messages = Vec::new();
        while let Some(event) = pass_stream.next().await {
            if let AgentEvent::Message(message) = event? {
                pass_messages.push(message);
            }
        }
        assert_eq!(provider.call_count.load(Ordering::SeqCst), 3);
        let pass_terminal = pass_messages
            .iter()
            .flat_map(|message| message.content.iter())
            .filter_map(MessageContent::as_system_notification)
            .find(|notification| {
                notification.notification_type == SystemNotificationType::TurnTerminal
            })
            .and_then(|notification| notification.data.as_ref())
            .expect("passing retry terminal");
        assert_eq!(pass_terminal["status"], "completed");
        assert_eq!(
            pass_terminal["retry_of_terminal_message_id"],
            failed_retry_terminal_id
        );

        let stale_stream = agent
            .reply_codepro_with_resume(
                Message::user()
                    .with_id("retry-user-stale")
                    .with_text("重新运行旧的失败验证"),
                SessionConfig {
                    id: session.id.clone(),
                    schedule_id: None,
                    max_turns: Some(8),
                    retry_config: None,
                },
                None,
                Some("retry-run-stale".to_string()),
                Some(CodeProResumeRequest {
                    normalized_user_input: None,
                    strategy: CodeProRetryStrategy::RetryFailedValidation,
                    checkpoint_id: None,
                    source_run_id: "source-run-1".to_string(),
                    source_user_message_id: "source-user-1".to_string(),
                    source_terminal_message_id: Some(source_terminal_id),
                    approval: None,
                }),
            )
            .await?;
        tokio::pin!(stale_stream);
        let mut stale_tool_requests = 0;
        let mut stale_status = None;
        while let Some(event) = stale_stream.next().await {
            if let AgentEvent::Message(message) = event? {
                stale_tool_requests += message
                    .content
                    .iter()
                    .filter(|content| matches!(content, MessageContent::ToolRequest(_)))
                    .count();
                stale_status = message
                    .content
                    .iter()
                    .filter_map(MessageContent::as_system_notification)
                    .find(|notification| {
                        notification.notification_type == SystemNotificationType::TurnTerminal
                    })
                    .and_then(|notification| notification.data.as_ref())
                    .map(|data| data["status"].clone())
                    .or(stale_status);
            }
        }
        assert_eq!(stale_tool_requests, 0);
        assert_eq!(stale_status, Some(serde_json::json!("failed")));
        assert_eq!(provider.call_count.load(Ordering::SeqCst), 3);
        assert_eq!(session_manager.list_all_sessions().await?.len(), 1);
        Ok(())
    }

