    #[tokio::test]
    async fn codepro_failed_validation_retry_cancels_in_flight_validation() -> Result<()> {
        let project = tempfile::tempdir()?;
        tokio::fs::write(project.path().join("app.rs"), "new\n").await?;
        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let agent = Agent::with_config(AgentConfig::new(
            session_manager,
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        ));
        let session = agent
            .config
            .session_manager
            .create_session(
                project.path().to_path_buf(),
                "cancel in-flight validation retry".to_string(),
                SessionType::CodePro,
                GooseMode::Auto,
            )
            .await?;
        let developer = get_enabled_extensions()
            .into_iter()
            .find(|extension| extension.name() == "developer")
            .expect("developer extension should be enabled");
        agent.add_extension(developer, &session.id).await?;
        let cancellation = CancellationToken::new();
        let command = if cfg!(windows) {
            "powershell -NoProfile -Command \"Start-Sleep -Seconds 30\""
        } else {
            "sleep 30"
        };
        let stream = agent
            .reply_codepro_failed_validation_retry(
                session.clone(),
                SessionConfig {
                    id: session.id.clone(),
                    schedule_id: None,
                    max_turns: None,
                    retry_config: None,
                },
                Some(cancellation.clone()),
                FailedValidationRetryRequest {
                    run_id: "retry-run-in-flight-cancel".to_string(),
                    source_user_message_id: "retry-user-in-flight-cancel".to_string(),
                    source_terminal_message_id: "failed-terminal-in-flight".to_string(),
                    source: Ok((
                        ValidationRetrySource {
                            terminal_message_id: "failed-terminal-in-flight".to_string(),
                            evidence:
                                crate::agents::codepro_validation_retry::ValidationRetryEvidence {
                                    target_path: project
                                        .path()
                                        .join("app.rs")
                                        .display()
                                        .to_string(),
                                    command: command.to_string(),
                                    exit_code: Some(1),
                                },
                        },
                        project.path().join("app.rs").canonicalize()?,
                    )),
                },
            )
            .await?;
        tokio::pin!(stream);

        let request = tokio::time::timeout(std::time::Duration::from_secs(5), stream.next())
            .await
            .expect("validation retry must publish its tool request")
            .transpose()?
            .expect("validation retry stream ended before dispatch");
        assert!(matches!(request, AgentEvent::Message(_)));

        let cancel_after_dispatch = cancellation.clone();
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(200)).await;
            cancel_after_dispatch.cancel();
        });
        let terminal_status = tokio::time::timeout(std::time::Duration::from_secs(5), async {
            let mut terminal_status = None;
            while let Some(event) = stream.next().await {
                if let AgentEvent::Message(message) = event? {
                    terminal_status = message
                        .content
                        .iter()
                        .filter_map(MessageContent::as_system_notification)
                        .find(|notification| {
                            notification.notification_type == SystemNotificationType::TurnTerminal
                        })
                        .and_then(|notification| notification.data.as_ref())
                        .map(|data| data["status"].clone())
                        .or(terminal_status);
                }
            }
            Ok::<_, anyhow::Error>(terminal_status)
        })
        .await
        .expect("in-flight validation cancellation must finish promptly")?;

        assert_eq!(terminal_status, Some(serde_json::json!("cancelled")));
        assert_eq!(
            tokio::fs::read_to_string(project.path().join("app.rs")).await?,
            "new\n"
        );
        Ok(())
    }

