    #[tokio::test]
    async fn unified_turn_read_only_answer_finishes_without_forced_budget_retry() -> Result<()> {
        let (data, errors) = unified_turn_case("default_boundary").await?;
        assert!(errors.is_empty(), "{errors:?}");
        let state = data
            .get_extension_state("codepro_unified_turn", "v1")
            .unwrap();
        // This provider returns prose without requesting work. There is no
        // exhausted operation to pause, even when max_turns is one.
        assert_eq!(state["status"], "finished");
        assert!(state["pause_reason"].is_null());
        Ok(())
    }

    #[tokio::test]
