    #[tokio::test]
    async fn unified_turn_cancelled_and_empty_responses_do_not_remain_running() -> Result<()> {
        for case in ["cancelled", "empty"] {
            let (data, errors) = unified_turn_case(case).await?;
            assert!(errors.is_empty(), "{case}: {errors:?}");
            let state = data
                .get_extension_state("codepro_unified_turn", "v1")
                .unwrap();
            assert_ne!(state["status"], "running", "{case}");
            assert_eq!(state["goal"], "保留这个原始目标");
            if case == "cancelled" {
                assert_eq!(state["pause_reason"], "cancelled");
            }
        }
        Ok(())
    }

