    #[tokio::test]
    async fn codepro_read_only_analysis_denies_mutating_shell_commands() -> Result<()> {
        let project = tempfile::tempdir()?;
        tokio::fs::write(project.path().join("Cargo.toml"), "[workspace]\n").await?;
        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let config = AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        );
        let agent = Agent::with_config(config);
        let session = session_manager
            .create_session(
                project.path().to_path_buf(),
                "CodePro shell guard".to_string(),
                SessionType::CodePro,
                GooseMode::Auto,
            )
            .await?;
        let developer = get_enabled_extensions()
            .into_iter()
            .find(|extension| extension.name() == "developer")
            .expect("developer extension should be enabled");
        agent.add_extension(developer, &session.id).await?;
        let provider = Arc::new(CodeProUnsafeShellProvider::default());
        agent
            .update_provider(
                provider.clone(),
                goose_providers::model::ModelConfig::new("mock-model"),
                &session.id,
            )
            .await?;
        let session_config = SessionConfig {
            id: session.id.clone(),
            schedule_id: None,
            max_turns: Some(20),
            retry_config: None,
        };

        let reply_stream = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            agent.reply_codepro_with_intent_for_test(
                session,
                Message::user().with_text("只分析 Cargo.toml，不要修改"),
                session_config,
                None,
                CodeProIntentDecision {
                    intent: CodeProIntent::ReadOnly,
                    clarification: None,
                    public_summary: None,
                    warning: None,
                },
                CodeProRunContext::default(),
            ),
        )
        .await
        .expect("read-only guard should return a denied tool result")?;
        tokio::pin!(reply_stream);
        let mut activity_events = Vec::new();
        while let Some(event) = reply_stream.next().await {
            if let AgentEvent::Message(message) = event? {
                for content in message.content {
                    if let MessageContent::SystemNotification(notification) = content {
                        if let Some(data) = notification.data {
                            if let Ok(activity) = serde_json::from_value::<ActivityEvent>(data) {
                                activity_events.push(activity);
                            }
                        }
                    }
                }
            }
        }

        assert_eq!(provider.call_count.load(Ordering::SeqCst), 2);
        assert_eq!(
            tokio::fs::read_to_string(project.path().join("Cargo.toml")).await?,
            "[workspace]\n"
        );
        assert_eq!(
            activity_events.len(),
            5,
            "activity events: {:?}",
            activity_events
                .iter()
                .map(|event| (&event.event_id, event.status))
                .collect::<Vec<_>>()
        );
        assert!(activity_events[0]
            .event_id
            .starts_with("intent-classification-msg_"));
        assert_eq!(activity_events[0].status, ActivityEventStatus::Running);
        assert_eq!(activity_events[1].event_id, activity_events[0].event_id);
        assert_eq!(activity_events[1].status, ActivityEventStatus::Completed);
        assert_eq!(activity_events[2].event_id, "thinking-unsafe-shell");
        assert_eq!(
            activity_events[2].event_type,
            ActivityEventKind::IntentCompleted
        );
        assert_eq!(activity_events[2].status, ActivityEventStatus::Completed);
        assert_eq!(activity_events[3].event_id, "unsafe-shell");
        assert_eq!(activity_events[3].status, ActivityEventStatus::Running);
        assert_eq!(activity_events[4].event_id, "unsafe-shell");
        assert_eq!(activity_events[4].status, ActivityEventStatus::Failed);
        Ok(())
    }

