    #[async_trait::async_trait]
    impl crate::providers::base::Provider for RetryingRecoveryCompactionProvider {
        async fn stream(
            &self,
            _model_config: &goose_providers::model::ModelConfig,
            _system_prompt: &str,
            messages: &[Message],
            _tools: &[Tool],
        ) -> Result<MessageStream, ProviderError> {
            let is_compaction = messages.len() == 1
                && messages[0]
                    .as_concat_text()
                    .starts_with("Please summarize the conversation history");
            if is_compaction {
                return self
                    .with_retry(|| async {
                        self.compaction_attempts.fetch_add(1, Ordering::SeqCst);
                        self.first_compaction_attempt_finished.notify_one();
                        Err(ProviderError::NetworkError(
                            "retry recovery compaction".to_string(),
                        ))
                    })
                    .await;
            }

            Ok(Box::pin(futures::stream::once(async {
                Err(ProviderError::ContextLengthExceeded(
                    "force recovery compaction".to_string(),
                ))
            })))
        }

        fn get_name(&self) -> &str {
            "retrying-recovery-compaction"
        }

        fn retry_config(&self) -> ProviderRetryConfig {
            ProviderRetryConfig::new(3, 5_000, 1.0, 5_000)
        }
    }

