        tokio::select! {
            _ = tokio::time::sleep(std::time::Duration::from_millis(500)) => {}
            result = &mut completion => panic!("recipe turn finished before its slow success check could be cancelled: {result:?}"),
        }
        assert_eq!(provider.call_count.load(Ordering::SeqCst), 1);
        cancel_token.cancel();

        tokio::time::timeout(std::time::Duration::from_secs(1), &mut completion)
            .await
