    #[tokio::test]
    async fn pre_tool_policy_hook_denial_is_durably_audited_without_dispatch() -> Result<()> {
        let temp_dir = tempfile::tempdir()?;
        let plugin_dir = temp_dir.path().join("pre-tool-blocker");
        std::fs::create_dir_all(plugin_dir.join("hooks"))?;
        let script_name = if cfg!(windows) {
            "block.cmd"
        } else {
            "block.sh"
        };
        let command = if cfg!(windows) {
            format!(r#""${{PLUGIN_ROOT}}/{script_name}""#)
        } else {
            // The fixture writes a regular file, not an executable plugin entry.
            format!(r#"sh "${{PLUGIN_ROOT}}/{script_name}""#)
        };
        let hooks = serde_json::json!({
            "hooks": {
                "PreToolUse": [{
                    "hooks": [{"type": "command", "command": command}]
                }]
            }
        });
        std::fs::write(
            plugin_dir.join("hooks/hooks.json"),
            serde_json::to_vec_pretty(&hooks)?,
        )?;
        #[cfg(windows)]
        std::fs::write(
            plugin_dir.join(script_name),
            "@echo blocked 1>&2\r\nexit /b 2\r\n",
        )?;
        #[cfg(not(windows))]
        std::fs::write(
            plugin_dir.join(script_name),
            "#!/bin/sh\necho blocked >&2\nexit 2\n",
        )?;

        let hook_manager =
            crate::hooks::HookManager::from_plugins_for_test(vec![DiscoveredPlugin {
                name: "pre-tool-blocker".into(),
                root: plugin_dir,
                scope: PluginScope::Project,
            }]);
        let data_dir = temp_dir.path().join("data");
        let provider = Arc::new(CountingTextProvider::new());
        let (agent, session_id) =
            create_test_agent(data_dir.clone(), hook_manager, provider).await?;
        let session = agent
            .config
            .session_manager
            .get_session(&session_id, false)
            .await?;
        let (_, result) = agent
            .dispatch_tool_call_with_confirmation(
                CallToolRequestParams::new("untrusted__write")
                    .with_arguments(serde_json::Map::new()),
                "hook-denied-request".to_string(),
                None,
                &session,
                false,
            )
            .await;
        let error = match result {
            Ok(_) => panic!("policy hook must stop dispatch"),
            Err(error) => error,
        };
        assert!(error.message.contains("denied by policy hook"));

        let audit_root = data_dir.join("audit").join("tool-audit-v2");
        let completed = std::fs::read_dir(audit_root)?
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_ok_and(|kind| kind.is_dir()))
            .filter(|entry| !entry.file_name().to_string_lossy().starts_with('.'))
            .flat_map(|entry| {
                std::fs::read_dir(entry.path())
                    .into_iter()
                    .flatten()
                    .filter_map(Result::ok)
            })
            .find(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .ends_with(".completed.json")
            })
            .expect("policy-hook denial must publish a completed audit record");
        let record: Value = serde_json::from_slice(&std::fs::read(completed.path())?)?;
        assert_eq!(record["authorization"], "policy_denied");
        assert_eq!(record["outcome"], "policy_denied");
        Ok(())
    }

