    async fn create_test_agent(
        data_dir: PathBuf,
        hook_manager: crate::hooks::HookManager,
        provider: Arc<dyn crate::providers::base::Provider>,
    ) -> Result<(Agent, String)> {
        let session_manager = Arc::new(SessionManager::new(data_dir.clone()));
        let permission_manager = Arc::new(PermissionManager::new(data_dir));
        struct TestRoutingProvider {
            inner: Arc<dyn crate::providers::base::Provider>,
            models: Vec<String>,
        }

        #[async_trait::async_trait]
        impl crate::providers::base::Provider for TestRoutingProvider {
            fn get_name(&self) -> &str {
                self.inner.get_name()
            }

            async fn stream(
                &self,
                model_config: &goose_providers::model::ModelConfig,
                system: &str,
                messages: &[Message],
                tools: &[Tool],
            ) -> Result<MessageStream, ProviderError> {
                self.inner
                    .stream(model_config, system, messages, tools)
                    .await
            }

            async fn fetch_supported_models(&self) -> Result<Vec<String>, ProviderError> {
                Ok(self.models.clone())
            }

            async fn validate_credentials(&self) -> Result<(), ProviderError> {
                Ok(())
            }
        }

        let routing = test_model_router_config();
        let mut models = vec![
            routing.planner_model,
            routing.coder_model,
            routing.tester_model,
            routing.reviewer_model,
        ];
        models.retain(|model| !model.trim().is_empty());
        models.sort();
        models.dedup();
        let routed_provider: Arc<dyn crate::providers::base::Provider> =
            Arc::new(TestRoutingProvider {
                inner: Arc::clone(&provider),
                models,
            });
        let provider_factory: ModelRouterProviderFactory = Arc::new(move |_, _, _| {
            let provider = Arc::clone(&routed_provider);
            Box::pin(async move { Ok(provider) })
        });
        let config = with_test_http_attempt_gate(AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        ))
        .with_model_router_provider_factory(provider_factory);
        let mut agent = Agent::with_config(config);
        agent.set_hook_manager_for_test(hook_manager);
        let session = session_manager
            .create_session(
                PathBuf::default(),
                "test".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await?;
        agent
            .update_provider(
                provider,
                goose_providers::model::ModelConfig::new("mock-model"),
                &session.id,
            )
            .await?;
        Ok((agent, session.id))
    }

    #[tokio::test]
    async fn failed_provider_preflight_has_zero_hooks_commands_or_prompt_persistence() -> Result<()>
    {
        let env = SessionStartHookTestEnv::new()?;
        let provider = Arc::new(ExpiringCredentialProvider::new());
        let (agent, session_id) =
            create_test_agent(env.data_dir(), env.hook_manager(), provider.clone()).await?;
        provider.credentials_valid.store(false, Ordering::SeqCst);

        let before = agent
            .config
            .session_manager
            .get_session(&session_id, true)
            .await?
            .conversation
            .map(|conversation| conversation.len())
            .unwrap_or_default();
        let session_config = SessionConfig {
            id: session_id.clone(),
            schedule_id: None,
            max_turns: Some(1),
            retry_config: None,
        };
        let mut local_query = agent
            .reply(
                Message::user().with_text("/goal"),
                session_config.clone(),
                None,
            )
            .await?;
        let mut local_events = 0;
        while let Some(event) = local_query.next().await {
            event?;
            local_events += 1;
        }
        let after_local = agent
            .config
            .session_manager
            .get_session(&session_id, true)
            .await?
            .conversation
            .map(|conversation| conversation.len())
            .unwrap_or_default();
        assert_eq!(
            (
                local_events,
                after_local,
                env.hook_log.exists(),
                provider.validation_count.load(Ordering::SeqCst),
                provider.stream_count.load(Ordering::SeqCst),
                agent.get_goal().await,
            ),
            (1, before, false, 0, 0, None),
            "a provider-free local query must be ephemeral and have no turn side effects"
        );

        let first = agent
            .reply(
                Message::user().with_text("/goal must not be persisted"),
                session_config.clone(),
                None,
            )
            .await;
        let failed = first.is_err();
        drop(first);
        let after = agent
            .config
            .session_manager
            .get_session(&session_id, true)
            .await?
            .conversation
            .map(|conversation| conversation.len())
            .unwrap_or_default();
        let hook_count = if env.hook_log.exists() {
            env.hook_invocations()?
        } else {
            0
        };
        assert_eq!(
            (
                failed,
                agent.get_goal().await,
                hook_count,
                after,
                provider.validation_count.load(Ordering::SeqCst),
                provider.stream_count.load(Ordering::SeqCst),
            ),
            (true, None, 0, before, 1, 0),
            "a failed preflight must be retryable and precede every turn side effect"
        );

        provider.credentials_valid.store(true, Ordering::SeqCst);
        let mut stream = agent
            .reply(
                Message::user().with_text("/goal retry with valid credentials"),
                session_config,
                None,
            )
            .await?;
        while let Some(event) = stream.next().await {
            event?;
        }
        assert_eq!(provider.validation_count.load(Ordering::SeqCst), 2);
        assert_eq!(provider.stream_count.load(Ordering::SeqCst), 1);
        assert_eq!(
            agent.get_goal().await.as_deref(),
            Some("retry with valid credentials")
        );
        Ok(())
    }

