    fn bounded_shell_request(id: &str, command: &str) -> ToolRequest {
        let call = CallToolRequestParams::new("developer__shell").with_arguments(
            json!({"command": command})
                .as_object()
                .expect("shell arguments")
                .clone(),
        );
        Message::assistant()
            .with_tool_request(id, Ok(call))
            .content
            .into_iter()
            .find_map(|content| match content {
                MessageContent::ToolRequest(request) => Some(request),
                _ => None,
            })
            .expect("tool request")
    }

