    #[test]
    fn explicit_no_tools_clears_a_prebound_execution_contract_only_when_applied() {
        let bound = || {
            UnifiedExecutorOptions::codepro_main_agent(CodeProTaskKind::ToolAction)
                .with_main_agent_control_run(RunId::new("run-memory-recall").unwrap())
                .unwrap()
        };
        let mut options = bound();
        let conversation = Conversation::new_unvalidated(vec![Message::user().with_text(
            "本项目的验收代号是什么？仅从已保存的项目记忆回答；没有记录就回复不知道。不要调用工具。",
        )]);
        assert!(apply_explicit_no_tools_constraint(
            &conversation,
            &mut options
        ));
        assert!(options.conversation_only);
        assert!(options.main_agent_control_task.is_none());
        assert!(!options.uses_main_agent_completion());

        let mut options = bound();
        let conversation = Conversation::new_unvalidated(vec![
            Message::user().with_text("请使用项目记忆工具保存本项目规则")
        ]);
        assert!(!apply_explicit_no_tools_constraint(
            &conversation,
            &mut options
        ));
        assert!(options.main_agent_control_task.is_some());
        assert!(options.uses_main_agent_completion());
    }

    #[test]
    fn project_memory_task_contract_budget_preserves_work_and_hard_cap() {
        let options = UnifiedExecutorOptions::codepro_project_memory_management();
        assert_eq!(options.task_kind, Some(CodeProTaskKind::ToolAction));
        assert!(options.uses_main_agent_completion());
        let limit = options.max_turns.unwrap() as usize;
        assert_eq!(limit, 8);
        for cap in [1, 4, limit] {
            let mut tracker =
                ActionBudgetTracker::from_config(options.action_budget_config.unwrap(), cap);
            // At the normal cap, inspect, revise, memory action, receipt inspection,
            // coverage and a recoverable protocol correction all fit before handoff.
            for turn in 1..cap {
                assert_eq!(
                    tracker.prepare_turn(turn),
                    ActionBudgetDecision::Execute,
                    "turn {turn}, cap {cap}"
                );
                tracker.observe_successful_tool_result();
            }
            assert_eq!(tracker.prepare_turn(cap), ActionBudgetDecision::Finalize);
            assert_eq!(
                tracker.prepare_turn(cap + 1),
                ActionBudgetDecision::Exhausted
            );
            assert_eq!(tracker.current_limit_turns(), cap);
        }
    }

    #[test]
    fn common_queries_conversation_boundary_rejects_workspace_tools_and_preserves_denial() {
        let tools = super::super::platform_extensions::common_queries::CommonQueriesClient::tools();
        for (name, expected) in [
            ("time_now", true),
            ("weather_get", true),
            ("location_resolve", true),
            ("shell", false),
            ("write", false),
            ("qwen_computer__click", false),
        ] {
            let request = ToolRequest {
                id: name.into(),
                tool_call: Ok(CallToolRequestParams::new(name)),
                metadata: None,
                tool_meta: None,
            };
            for host_denied in [false, true] {
                let mut permissions = PermissionCheckResult {
                    approved: if host_denied {
                        vec![]
                    } else {
                        vec![request.clone()]
                    },
                    needs_approval: vec![],
                    denied: if host_denied {
                        vec![request.clone()]
                    } else {
                        vec![]
                    },
                };
                enforce_codepro_read_only_permissions(
                    &mut permissions,
                    std::slice::from_ref(&request),
                    &tools,
                );
                assert_eq!(
                    !permissions.approved.is_empty(),
                    expected && !host_denied,
                    "{name}"
                );
                assert_eq!(
                    !permissions.denied.is_empty(),
                    !expected || host_denied,
                    "{name}"
                );
            }
            let mut permissions = PermissionCheckResult {
                approved: vec![request.clone()],
                needs_approval: vec![],
                denied: vec![],
            };
            enforce_codepro_read_only_permissions(
                &mut permissions,
                std::slice::from_ref(&request),
                &[],
            );
            assert!(
                permissions.approved.is_empty(),
                "explicit no-tools must reject {name}"
            );
        }
    }

    #[test]
    fn read_only_analysis_accepts_deferred_current_tools_and_preserves_denials() {
        let recall = Tool::new("memory_service__recall", "Recall", serde_json::Map::new())
            .annotate(rmcp::model::ToolAnnotations::default().read_only(true));
        let request = ToolRequest {
            id: "resume-recall".to_string(),
            tool_call: Ok(CallToolRequestParams::new("memory_service__recall")),
            metadata: None,
            tool_meta: None,
        };
        let surface = super::super::analysis_tools::AnalysisTools::new(vec![recall], vec![]);
        assert!(!surface
            .offered()
            .iter()
            .any(|tool| tool.name == "memory_service__recall"));
        for denied in [false, true] {
            let mut permissions = PermissionCheckResult {
                approved: if denied {
                    vec![]
                } else {
                    vec![request.clone()]
                },
                needs_approval: vec![],
                denied: if denied {
                    vec![request.clone()]
                } else {
                    vec![]
                },
            };
            enforce_codepro_read_only_permissions(
                &mut permissions,
                std::slice::from_ref(&request),
                surface.catalog(),
            );
            assert_eq!(permissions.approved.len(), usize::from(!denied));
            assert_eq!(permissions.denied.len(), usize::from(denied));
        }
        // Removing the extension from the current catalog revokes access, even with old history.
        let mut permissions = PermissionCheckResult {
            approved: vec![request.clone()],
            needs_approval: vec![],
            denied: vec![],
        };
        enforce_codepro_read_only_permissions(
            &mut permissions,
            std::slice::from_ref(&request),
            &[],
        );
        assert!(permissions.approved.is_empty());
        assert_eq!(permissions.denied.len(), 1);
    }

