    fn bounded_worker_auto_allows_internal_todo_state() {
        let call = CallToolRequestParams::new("todo__todo_write").with_arguments(
            json!({"content": "- [ ] run tests"})
                .as_object()
                .expect("todo arguments")
                .clone(),
        );
        let request = Message::assistant()
            .with_tool_request("todo", Ok(call))
            .content
            .into_iter()
            .find_map(|content| match content {
                MessageContent::ToolRequest(request) => Some(request),
                _ => None,
            })
            .expect("todo request");
        let mut permissions = PermissionCheckResult {
            approved: vec![],
            needs_approval: vec![],
            denied: vec![request.clone()],
        };

        enforce_codepro_bounded_worker_shell_permissions(
            &mut permissions,
            std::slice::from_ref(&request),
            None,
        );

        assert_eq!(permissions.approved.len(), 1);
        assert!(permissions.denied.is_empty());
    }

    #[test]
    fn bounded_tester_rejects_chained_and_parallel_shell_calls_before_approval() {
        let chained = bounded_shell_request("chained", "node --version && npm test");
        let first = bounded_shell_request("first", "npm test");
        let parallel = bounded_shell_request("parallel", "node --test");
        let requests = vec![chained.clone(), first.clone(), parallel.clone()];
        let mut permissions = PermissionCheckResult {
            approved: vec![],
            needs_approval: requests.clone(),
            denied: vec![],
        };

        let not_run =
            enforce_codepro_bounded_worker_shell_permissions(&mut permissions, &requests, None);

        assert_eq!(
            permissions
                .approved
                .iter()
                .map(|request| request.id.as_str())
                .collect::<Vec<_>>(),
            vec!["first"]
        );
        assert!(permissions.needs_approval.is_empty());
        assert!(permissions.denied.is_empty());
        assert_eq!(
            not_run
                .iter()
                .map(|rejection| rejection.request.id.as_str())
                .collect::<Vec<_>>(),
            vec!["chained", "parallel"]
        );
        let rejected = bounded_shell_rejection_result(not_run[0].reason);
        assert!(!codepro_call_tool_result_skipped(&rejected));
    }

    #[test]
    fn extract_string_arg_picks_first_present_key() {
        let input = serde_json::json!({ "file_path": "/tmp/a.txt", "path": "/tmp/b.txt" });
        assert_eq!(
            extract_string_arg(&input, &["path", "file", "file_path"]).as_deref(),
            Some("/tmp/b.txt")
        );
        let input = serde_json::json!({ "file_path": "/tmp/a.txt" });
        assert_eq!(
            extract_string_arg(&input, &["path", "file", "file_path"]).as_deref(),
            Some("/tmp/a.txt")
        );
        let input = serde_json::json!({ "other": 1 });
        assert!(extract_string_arg(&input, &["path"]).is_none());
        let input = serde_json::json!({ "path": "" });
        assert!(extract_string_arg(&input, &["path"]).is_none());
    }

    #[test]
    fn attach_turn_usage_targets_last_assistant_message() {
        let usage = ProviderUsage::new(
            "test-model".to_string(),
            Usage::new(Some(1200), Some(340), None),
        );
        let mut conversation = Conversation::new_unvalidated([
            Message::user().with_text("hi"),
            Message::assistant().with_id("a1").with_text("first"),
            Message::user().with_text("again"),
            Message::assistant().with_id("a2").with_text("second"),
        ]);

        let (message_id, attached) =
            attach_turn_usage(&mut conversation, &usage).expect("usage should attach");

        assert_eq!(message_id.as_deref(), Some("a2"));
        assert_eq!(attached.input_tokens, Some(1200));
        assert_eq!(attached.output_tokens, Some(340));
        assert!(!attached.is_compaction, "turn usage is not a compaction");

        let messages = conversation.messages();
        let stored = messages[3]
            .metadata
            .usage
            .as_deref()
            .expect("usage must be stored on the last assistant message");
        assert_eq!(*stored, attached);
        assert!(
            messages[1].metadata.usage.is_none(),
            "earlier assistant message must not receive the usage"
        );
    }

