    #[test]
    fn evidence_timeout_does_not_invent_l3_or_an_invalid_root_recovery() {
        use crate::agents::codepro_terminal_report::{
            CodeProTerminalOutcome, ReportRecoveryAction,
        };
        let risk = CodeProRiskAssessment {
            tier: CodeProRiskTier::L0ReadOnly,
            reasons: vec![CodeProRiskReason::FocusedLocalValidation],
        };

        let facts = build_codepro_evidence_capture_failure_facts(
            "analyze and test the project",
            CodeProTaskKind::ProjectTest,
            &risk,
            Path::new("D:/project"),
            &EvidenceCaptureOutcome::TimedOut {
                operation: "legacy git add -A --".to_string(),
            },
        );

        assert_eq!(facts.outcome, CodeProTerminalOutcome::SchedulingFailed);
        assert_eq!(facts.recovery_action, ReportRecoveryAction::RetryPlanning);
        assert_eq!(facts.limitations, vec!["evidence_capture_timed_out"]);
        assert_eq!(facts.risk_tier, CodeProRiskTier::L0ReadOnly);
        assert!(!facts.review_required);
        assert!(!facts.completion_allowed);
        assert_eq!(facts.classification_counts.codepro_incomplete, 1);
    }

