    #[tokio::test]
    async fn checkpoint_classifier_uses_the_session_provider_and_model_after_a_switch() -> Result<()>
    {
        struct ClassifierProvider {
            name: &'static str,
            models: std::sync::Mutex<Vec<String>>,
        }

        #[async_trait::async_trait]
        impl crate::providers::base::Provider for ClassifierProvider {
            fn get_name(&self) -> &str {
                self.name
            }

            async fn stream(
                &self,
                model_config: &goose_providers::model::ModelConfig,
                _system: &str,
                _messages: &[Message],
                _tools: &[Tool],
            ) -> Result<MessageStream, ProviderError> {
                self.models
                    .lock()
                    .unwrap()
                    .push(model_config.model_name.to_string());
                let message = Message::assistant().with_text(
                    r#"{"kind":"inspect","task_id":null,"command":null,"clarification":null}"#,
                );
                let usage =
                    ProviderUsage::new(model_config.model_name.to_string(), Usage::default());
                Ok(stream_from_single_message(message, usage))
            }
        }

        let data = tempfile::tempdir()?;
        let session_manager = Arc::new(SessionManager::new(data.path().join("sessions")));
        let permission_manager = Arc::new(PermissionManager::new(data.path().join("permissions")));
        let agent = Agent::with_config(with_test_http_attempt_gate(AgentConfig::new(
            session_manager.clone(),
            permission_manager,
            None,
            GooseMode::Auto,
            true,
            GoosePlatform::GooseCli,
        )));
        let session = session_manager
            .create_session(
                data.path().to_path_buf(),
                "checkpoint classifier".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await?;
        let provider_a = Arc::new(ClassifierProvider {
            name: "provider-a",
            models: std::sync::Mutex::new(Vec::new()),
        });
        let provider_b = Arc::new(ClassifierProvider {
            name: "provider-b",
            models: std::sync::Mutex::new(Vec::new()),
        });
        agent
            .update_provider(
                provider_a.clone(),
                goose_providers::model::ModelConfig::new("model-a"),
                &session.id,
            )
            .await?;
        agent
            .update_provider(
                provider_b.clone(),
                goose_providers::model::ModelConfig::new("model-b"),
                &session.id,
            )
            .await?;
        let selected = session_manager.get_session(&session.id, false).await?;
        let (mut old_state, _) = checkpoint_input_fixture();
        old_state.run_id = session.id.clone();
        let decision = agent
            .interpret_codepro_checkpoint_input(
                &selected,
                &old_state,
                checkpoint_input_context(&old_state),
                &Message::user().with_text("这个问题该怎么理解？"),
                None,
            )
            .await?;
        assert!(matches!(
            decision,
            CodeProCheckpointInputDecision::Inspect(_)
        ));
        assert!(provider_a.models.lock().unwrap().is_empty());
        assert_eq!(&*provider_b.models.lock().unwrap(), &["model-b"]);
        assert_eq!(old_state.status, CodeProRunStatus::Paused);
        Ok(())
    }

    #[test]
    fn checkpoint_input_new_goals_and_cancel_do_not_resume_or_authorize() {
        let (state, _) = checkpoint_input_fixture();
        for input in [
            "先别改，只分析app.ts",
            "解释“继续”是什么意思",
            "只解释截图，不继续之前的修改",
        ] {
            let decision = checkpoint_input_decision(
                &state,
                checkpoint_input_context(&state),
                &Message::user().with_text(input),
            );
            let decision = match decision {
                CodeProCheckpointInputDecision::Classify(context) => {
                    checkpoint_input_semantic_decision(
                        context,
                        parse_semantic_intent_for_message(
                            r#"{"intent":"read_only","clarification":null}"#,
                            input,
                        ),
                    )
                }
                other => other,
            };
            assert!(
                matches!(decision, CodeProCheckpointInputDecision::Inspect(_)),
                "{input}"
            );
        }
        for input in ["取消当前任务", "停止", "不要继续了"] {
            assert!(matches!(
                checkpoint_input_decision(
                    &state,
                    checkpoint_input_context(&state),
                    &Message::user().with_text(input)
                ),
                CodeProCheckpointInputDecision::Notice {
                    cancelled: true,
                    ..
                }
            ));
        }
        let input = "修改 app.ts 为新的登录页面";
        let CodeProCheckpointInputDecision::Classify(context) = checkpoint_input_decision(
            &state,
            checkpoint_input_context(&state),
            &Message::user().with_text(input),
        ) else {
            panic!("unconstrained new goal requires semantic interpretation");
        };
        assert!(matches!(checkpoint_input_semantic_decision(context,
                parse_semantic_intent_for_message(r#"{"intent":"change","clarification":null}"#, input)),
            CodeProCheckpointInputDecision::Notice { text, cancelled: false, .. } if text.contains("新任务")));
    }

