    #[test]
    fn checkpoint_input_skip_leaves_unrelated_paused_work_and_goal_unchanged() {
        use crate::agents::task_dag::TaskStatus;
        let (mut state, retry) = checkpoint_input_fixture();
        let mut unrelated = state.dag.tasks[0].clone();
        unrelated.id = "unrelated-validation".to_string();
        unrelated.name = "verify deployment configuration".to_string();
        unrelated.description = "inspect deployment prerequisites".to_string();
        unrelated.output = None;
        state.dag.tasks.push(unrelated);
        state.dag = crate::agents::task_dag::TaskDAG::new(&state.goal, state.dag.tasks);
        state.dag.task_kind = Some(CodeProTaskKind::ProjectTest);
        for contract in state.dag.contracts.values_mut() {
            contract.write_scope = vec!["tests/.tmp/**".to_string()];
        }
        state
            .dag
            .ensure_action_budget(CodeProTaskKind::ProjectTest)
            .unwrap();
        state.dag.validate().expect("valid paused fixture");
        assert!(state.dag.contract_violations().is_empty());
        let goal = state.goal.clone();
        let resumed = prepare_codepro_resume_state_from_published_checkpoint(
            state,
            Path::new("C:/workspace"),
            Some("checkpoint-r1-e14"),
            Some(&retry),
            Some("跳过该命令，只做静态分析。"),
        )
        .expect("the matched validation can be skipped without resuming unrelated work");
        assert_eq!(resumed.goal, goal);
        assert_eq!(resumed.dag.tasks[0].status, TaskStatus::Skipped);
        assert_eq!(resumed.dag.tasks[1].status, TaskStatus::Paused);
    }

    #[test]
    fn user_input_checkpoint_resume_needs_no_scope_approval_and_honors_skip() {
        use crate::agents::task_dag::{
            ExecutionOutcome, TaskNode, TaskOutput, TaskStatus, VerificationEvidenceV1,
            VerificationOutcomeV1,
        };

        let working_dir = PathBuf::from("C:/workspace");
        let mut dag = crate::agents::task_dag::TaskDAG::new(
            "analyze project",
            vec![TaskNode {
                id: "test".to_string(),
                name: "analyze and test".to_string(),
                description: "discover the project validation entry".to_string(),
                role: AgentRole::Tester,
                depends_on: Vec::new(),
                acceptance_criteria: "report verified and unverified findings".to_string(),
                status: TaskStatus::Paused,
                output: Some(TaskOutput {
                    change_report: "WAITING_FOR_USER: provide a command or choose static analysis"
                        .to_string(),
                    test_results: Some(
                        "workspace_discovery_not_found\nreason:no supported test entry".to_string(),
                    ),
                    ..TaskOutput::default()
                }),
                retry_count: 0,
            }],
        );
        dag.task_kind = Some(CodeProTaskKind::ProjectTest);
        dag.contracts.get_mut("test").unwrap().write_scope = vec!["tests/.tmp/**".to_string()];
        dag.ensure_action_budget(CodeProTaskKind::ProjectTest)
            .unwrap();
        let state = CodeProRunState {
            run_id: "session-input".to_string(),
            goal: "analyze project".to_string(),
            source_repo: working_dir.clone(),
            worktree_path: working_dir.clone(),
            workspace: None,
            status: CodeProRunStatus::Paused,
            pause_reason: Some(CodeProPauseReason::UserInputRequired),
            workflow: Some(CodeProWorkflow::Test),
            last_active_run_id: Some("source-run-input".to_string()),
            dag,
            router_config: crate::agents::model_router::ModelRouterConfig::default(),
            reviewer_action_budget: None,
            review_result: None,
            final_report: None,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
        };
        let retry = CodeProResumeRequest {
            normalized_user_input: None,
            strategy: CodeProRetryStrategy::ContinueCheckpoint,
            checkpoint_id: Some("checkpoint-r1-e14".to_string()),
            source_run_id: "source-run-input".to_string(),
            source_user_message_id: "source-user-input".to_string(),
            source_terminal_message_id: None,
            approval: None,
        };

        let mut validated = state.clone();
        assert!(apply_codepro_plain_user_input(
            &mut validated,
            "跳过该命令，只做静态分析，不要修改文件。"
        ));
        assert!(LegacyReadyAdapter::validate(&validated.dag).is_ok());
        assert!(!validated.dag.has_exhausted_completion_checkpoint());
        assert!(validated
            .dag
            .ensure_action_budget(CodeProTaskKind::ProjectTest)
            .is_ok());
        validated
            .dag
            .validate()
            .expect("skipped user-input task must remain a valid DAG");
        assert!(validated.dag.contract_violations().is_empty());

        let resumed = prepare_codepro_resume_state_from_published_checkpoint(
            state,
            &working_dir,
            Some("checkpoint-r1-e14"),
            Some(&retry),
            Some("跳过该命令，只做静态分析，不要修改文件。"),
        )
        .expect("ordinary user input must resume without a permission approval");

        assert_eq!(resumed.dag.tasks[0].status, TaskStatus::Skipped);
        assert!(codepro_skipped_dynamic_validation(&resumed.dag));
        let risk = crate::agents::agent_role::CodeProRiskAssessment {
            tier: crate::agents::agent_role::CodeProRiskTier::L2Feature,
            reasons: vec![
                crate::agents::agent_role::CodeProRiskReason::MultiFileOrUnknownWriteScope,
            ],
        };
        assert_eq!(
            codepro_recovery_decision_for_run(&resumed.dag, &[], &risk, 0),
            (CodeProRecoveryDecision::Proceed, None)
        );
        assert!(resumed.dag.tasks[0]
            .output
            .as_ref()
            .unwrap()
            .change_report
            .contains("用户已确认跳过动态验证命令"));

        let mut prerequisite_state = resumed;
        prerequisite_state.status = CodeProRunStatus::Paused;
        prerequisite_state.pause_reason = Some(CodeProPauseReason::UserInputRequired);
        prerequisite_state.dag.tasks[0].status = TaskStatus::Paused;
        prerequisite_state.dag.tasks[0].output = Some(TaskOutput {
            change_report: "WAITING_FOR_USER: start the local API service or skip this command"
                .to_string(),
            test_results: Some(
                "host_verification_receipt\noutcome:PrerequisiteUnavailable;exit_code:1"
                    .to_string(),
            ),
            ..TaskOutput::default()
        });
        prerequisite_state.dag.verification_evidence_v1.insert(
            "test".to_string(),
            vec![VerificationEvidenceV1 {
                schema_version: 1,
                assertion_id: "api-test".to_string(),
                expected: "exit_code:0".to_string(),
                observed_summary: "outcome:PrerequisiteUnavailable;exit_code:1".to_string(),
                exit_code: Some(1),
                outcome: VerificationOutcomeV1::Failed,
                artifact_sha256: None,
                recorded_at: chrono::Utc::now(),
                tool_ref: "host_verification_v1".to_string(),
                failure_epoch: 1,
                execution_outcome: ExecutionOutcome::WaitingForUser,
                repair_context: None,
            }],
        );

        assert!(apply_codepro_plain_user_input(
            &mut prerequisite_state,
            "跳过该命令，只做静态分析，不要修改文件。"
        ));
        assert_eq!(prerequisite_state.dag.tasks[0].status, TaskStatus::Skipped);
        assert!(prerequisite_state.dag.tasks[0]
            .output
            .as_ref()
            .and_then(|output| output.test_results.as_deref())
            .is_some_and(|evidence| evidence.contains("result:NOT_RUN")));
    }

